function applyVariableRoles(roles, sync, invalidatePreview) {
  const beforeFeatures = currentVariableRoles().features.map(variableRoleRefId);
  const normalized = normalizeVariableRoles(roles || {});
  if (oocvAutomaticFeatureMappingActive()) OOCV_AUTO_FEATURE_REFS = variableRoleRefs(normalized.features);
  restoreSharedKeyOrderFromRoles(normalized);
  const afterFeatures = normalized.features.map(variableRoleRefId);
  const featuresChanged = beforeFeatures.length !== afterFeatures.length || beforeFeatures.some((v, i) => v !== afterFeatures[i]);
  renderVariableRoleControls(normalized);
  syncVariableInputs();
  if (invalidatePreview !== false) invalidateMaterialization();
  // Selector masks are late state. Keep them intact until a scientific change has actually
  // invalidated Preview; a cancelled invalidation must restore the complete selector state.
  if (featuresChanged && !LAST_PREVIEW_RESULT && matrixState && matrixState.selection) {
    matrixState.selection.selFeats = [];
    delete matrixState.selection.selFeatsFile;
  }
  if (sync !== false) { matrixStateFromForm(); scheduleCommonLabelDefinitionProbe(); }
}
