  const nameSourceId = val('di_common_label_names_var');
  const names = Array.from(document.querySelectorAll('.commonLabelNameInput')).map((el) => String(el.value || '').trim());
  def.kind = val('di_modeflag') === 'regression' ? 'label_names' : 'group_names';
  def.count = Number(LABEL_DEFINITION_PROBE.count || names.length || 0);
  def.sourceCodes = arr(LABEL_DEFINITION_PROBE.sourceCodes).map((x) => String(x));
