function restorePreviewRuntimeState() {
  if (!LAST_PREVIEW_RUNTIME_STATE) return;
  const x = JSON.parse(JSON.stringify(LAST_PREVIEW_RUNTIME_STATE));
  SOURCE_VARIABLES=x.sourceVariables || []; SOURCE_VARIABLE_NAMES=x.sourceVariableNames || []; TABLE_VARIABLE_CATALOG=x.tableVariableCatalog || [];
  SHEETS=x.sheets || []; DATABASE_TABLES=x.databaseTables || []; TABULAR_FILTERS=x.tabularFilters || []; TABULAR_FILTER_DRAFTS=x.tabularFilterDrafts || {};
  TABLE_FILE_DISCOVERY_SIGNATURE=String(x.tableFileDiscoverySignature || ''); TABLE_FILE_REFRESH_DIRTY=x.tableFileRefreshDirty === true;
  APPLIED_SHARED_KEY_NAMES=x.appliedSharedKeyNames || [];
  Object.keys(KEY_COMPONENT_ORDER).forEach((k)=>delete KEY_COMPONENT_ORDER[k]); Object.assign(KEY_COMPONENT_ORDER,x.keyComponentOrder || {});
  IMAGE_AUX_SOURCE_VARIABLES=x.imageAuxSourceVariables || []; IMAGE_GLOBAL_SOURCE_VARIABLES=x.imageGlobalSourceVariables || [];
  SUBJECT_FILE_CLASS_LISTS=x.subjectFileClassLists || []; SUBJECT_FILE_ACTIVE_CLASS_INDEX=Number(x.subjectFileActiveClassIndex || 0);
  ATLAS_DESCRIPTOR_INSPECTION=x.atlasDescriptorInspection || null; CONNECTIVITY_DESCRIPTOR_INSPECTION=x.connectivityDescriptorInspection || null;
  CONNECTIVITY_TABLE_SCHEMA=x.connectivityTableSchema || null;
}

function restorePreviewInputState() {
  if (!LAST_PREVIEW_INPUT_STATE) return;
  const runtimeState = LAST_PREVIEW_RUNTIME_STATE ? JSON.parse(JSON.stringify(LAST_PREVIEW_RUNTIME_STATE)) : null;
  const currentDesc = val('di_desc');
  const currentSelection = matrixState && matrixState.selection && typeof matrixState.selection === 'object'
    ? JSON.parse(JSON.stringify(matrixState.selection)) : null;
  const restored = JSON.parse(JSON.stringify(LAST_PREVIEW_INPUT_STATE));
  delete restored.materializationRevision;
  if (currentDesc !== undefined) restored.desc_data = currentDesc;
  if (currentSelection) {
    const previewSource = String(restored.sourceType || ((restored.matrix || {}).sourceType || '')).trim().toLowerCase();
    if (['workspace','matfile','tablefile','tablevar','database'].includes(previewSource)) restored.selection = currentSelection;
    else if (Array.isArray(currentSelection.selCases)) {
      restored.selection = restored.selection && typeof restored.selection === 'object' ? restored.selection : {};
      restored.selection.selCases = currentSelection.selCases.slice();
    }
  }
  matrixState = restored;
  STATE.matrixImport = matrixState;
  formFromMatrixState();
  if (runtimeState) {
    LAST_PREVIEW_RUNTIME_STATE = runtimeState;
    restorePreviewRuntimeState();
    const src = sourceType();
    if (['tablefile','tablevar','database'].includes(src)) {
      const m = matrixState && matrixState.matrix ? matrixState.matrix : {};
      setSheetOptions(SHEETS, arr(m.sheets).length ? m.sheets : (m.sheet || []));
      applyVariableRoles(m.variableRoles || {}, false, false);
      renderTableVariableSelector();
      renderTabularFilterSummary();
      setAppliedSharedKeyStatus(APPLIED_SHARED_KEY_NAMES);
    }
  }
  updateSourcePanels();
  updateActionButtons();
}

/**
 * invalidateMaterialization  Confirm and invalidate a retained Preview after a materialization-changing input edit.
 * Subject inclusion/exclusion and diagnostics/QC presentation state deliberately bypass this function.
 */
function confirmMaterializationInvalidation(message) {
  let proceed = true;
  try {
    proceed = confirm(message || 'This change makes the current Preview out of date. You will need to run Preview again. Continue?');
  } catch (_) { proceed = true; }
  return proceed;
}
function confirmTableFileListChange() {
  if (!LAST_PREVIEW_RESULT || !LAST_PREVIEW_INPUT_STATE) return true;
  const previewFiles=arr((LAST_PREVIEW_INPUT_STATE.matrix || {}).tableFiles).map((x)=>String(x).trim()).filter(Boolean).join('\n');
  if (tableFileListSignature() === previewFiles) return true;
  if (!confirmMaterializationInvalidation('Changing the table-file list discards the current Preview and Matrix Inspector selection. You will need to refresh data sources and run Preview again. Continue?')) {
    restorePreviewInputState();
    setMessage('Table-file change cancelled. The current Preview, source inventory, assignments, and Matrix Inspector selection remain valid.','info');
    return false;
  }
  clearMaterialization(true);
  return true;
}
function invalidateMaterialization() {
  if (LAST_PREVIEW_RESULT && LAST_PREVIEW_INPUT_STATE) {
    const current = JSON.parse(JSON.stringify(matrixStateFromForm(false, false)));
    current.materializationRevision = MATERIALIZATION_REVISION;
    if (sameMaterializationInputs(current, LAST_PREVIEW_INPUT_STATE)) return false;
    if (!confirmMaterializationInvalidation()) {
      restorePreviewInputState();
      setMessage('Change cancelled. The current Preview remains valid.', 'info');
      return false;
    }
  }
  const hadMaterialization = clearMaterialization(true);
  if (hadMaterialization) {
    setMessage('The import inputs changed after Preview. Run Preview again before Commit.', 'warn');
  }
  return hadMaterialization;
}

/**
 * materializationStateFromForm  Build the single browser request state for operations that must address the current retained materialization.
 */
function materializationStateFromForm() {
  const st = JSON.parse(JSON.stringify(matrixStateFromForm(false, false)));
  st.materializationRevision = MATERIALIZATION_REVISION;
  return st;
}

