    target.globalSource = 'user';
    target.globalUserSourceType = 'workspace';
    target.globalAlignmentMode = 'case_id';
    target.globalVariableRoles = { caseId:[], labels:[], features:[], featureNames:[], covariates:[], covariateNames:[], globals:[] };
