function sourceTypeFromMatrixState(st, m) {
  st = st || {};
  m = m || {};
  const declared = String(st.sourceType || m.sourceType || '').trim().toLowerCase();
  const sourceFamily = String(st.sourceFamily || m.sourceFamily || ((st.connectivity || {}).sourceFamily || '')).trim().toLowerCase();

  // Resume/modify helpers may attach shared label/covariate metadata under
  // state.image even for matrix/table imports.  A concrete persisted matrix
  // source type must therefore win over incidental image metadata.
  if (['tablefile', 'tablevar', 'database', 'matfile'].includes(declared)) return declared;
  if (declared === 'connectivity' || sourceFamily === 'connectivity') return 'connectivity';
  if (declared === 'roi' || sourceFamily === 'roi' || st.roi) return 'roi';

  const ds = String(st.datasource || m.datasource || '').toLowerCase();
  const gm = Number(st.groupmode !== undefined ? st.groupmode : m.groupmode);
  if (declared === 'workspace' && (ds === '' || ds === 'matrix') && (!Number.isFinite(gm) || gm === 1)) return 'workspace';
  const hasSurfaceFields = ds === 'surf' || declared === 'surface-list';
  const hasImageFields = !!(st.image || st.imageFiles || st.maskFile || st.brainmask || ds === 'nifti' || ds === 'spm' || ds === 'image' || hasSurfaceFields || st.groupmode === -2);
  return hasSurfaceFields ? 'surface-list' : (hasImageFields ? 'image-list' : (declared || (st.groupmode === 6 ? 'database' : (st.groupmode === 5 ? 'tablevar' : (st.groupmode === 2 ? 'matfile' : (st.groupmode === 3 || st.groupmode === 4 ? 'tablefile' : 'workspace'))))));
}

