  setVal('di_var_covarnames_manual', arr(m.covariateNameList).join(', '));
  if (src === 'tablevar') { const tables=arr(m.tableVariables).filter((v)=>v && v!=='?'); if (!tables.length && m.M_edit && m.M_edit !== '?') tables.push(m.M_edit); setOptions('di_tablevar_select',tables,tables); }
  renderTableVariableSelector();
