/**
 * setMessage  Provide the set message helper used by DataIO browser page for import configuration, preview, QC and commit operations.
 * It is a browser rendering helper: it updates DOM or SVG state from already retrieved NeuroMiner payloads and does not define new scientific results.
 * Side effects: updates DOM markup, CSS classes or control state for the active browser page.
 */
function setMessage(txt, kind) {
  const text = txt || '';
  const level = kind || 'info';
  window.NMUIMessageTools.setMessage(text, level);
  const overviewEl = document.getElementById('message');
  if (overviewEl) {
    overviewEl.textContent = '';
    overviewEl.className = 'message hidden';
  }
}
/**
 * stripKind  Provide the strip kind helper used by DataIO browser page for import configuration, preview, QC and commit operations.
 * It supports DataIO browser page for import configuration, preview, QC and commit operations at a local helper boundary rather than changing MATLAB-side NeuroMiner state.
 */
function stripKind(res) { return (res && res.strip && res.strip.level) || (res && res.ok ? 'ok' : 'danger'); }
/**
 * stripText  Build the strip text shown to users in the browser UI.
 * It supports DataIO browser page for import configuration, preview, QC and commit operations at a local helper boundary rather than changing MATLAB-side NeuroMiner state.
 */
function stripText(res, fallback) {
  if (!res) return fallback || 'Done.';
  const msgs = arr(res.messages);
  const hasBlocking = res.blocking === true || msgs.some((m) => m && m.blocking === true);
  if (!hasBlocking) {
    return (res.message || (res.strip && res.strip.text)) || fallback || 'Done.';
  }
  const descMessages = [];
  const labelMessages = [];
  const nonFiniteMessages = [];
  const blockingMessages = [];
  msgs.forEach((m) => {
    const level = String(m.level || '').toLowerCase();
    const txt = String(m.text || '').trim();
    const src = String(m.source || '').toLowerCase();
    if (!txt || (level !== 'warn' && level !== 'danger')) return;
    if (m.blocking === true && !blockingMessages.includes(txt)) blockingMessages.push(txt);
    const isDescription = src.includes('preparematrixio') || /data description|modality description|description is missing|description is required/i.test(txt);
    const isLabel = src.includes('label') || /\blabel\b|label vector|label array|label imputation/i.test(txt);
    const isNonFinite = /non-finite|nan|inf/i.test(txt);
    if (isDescription && !descMessages.includes(txt)) {
      descMessages.push(txt);
    } else if (isLabel && !labelMessages.includes(txt)) {
      labelMessages.push(txt);
    } else if (isNonFinite && !nonFiniteMessages.includes(txt)) {
      nonFiniteMessages.push(txt);
    }
  });
  const notable = blockingMessages.concat(descMessages, labelMessages, nonFiniteMessages);
  if (notable.length) {
    const suffix = msgs.length ? `\n(${msgs.length} DataIO diagnostic message(s); use Open diagnostics / Import task diagnostics for details.)` : '';
    return notable.slice(0, 3).join('\n') + suffix;
  }
  return (res.message || (res.strip && res.strip.text)) || fallback || 'Done.';
}
/**
 * switchTab  Provide the switch tab helper used by DataIO browser page for import configuration, preview, QC and commit operations.
 * It is a browser rendering helper: it updates DOM or SVG state from already retrieved NeuroMiner payloads and does not define new scientific results.
 * Side effects: updates DOM markup, CSS classes or control state for the active browser page.
 */
function switchTab(name) {
  const target = name || 'overview';
  const activeTab = document.querySelector('.tab.active');
  const current = activeTab && activeTab.dataset ? String(activeTab.dataset.tab || '') : '';
  if (current && current !== target) closeDataIOHelp();
  if (document.body) document.body.classList.toggle('dataioOverviewActive', target === 'overview');
  document.querySelectorAll('.tab').forEach((b) => b.classList.toggle('active', b.dataset.tab === target));
  document.querySelectorAll('.tabPage').forEach((p) => p.classList.toggle('active', p.id === 'tab_' + target));
  updateModeNavigation();
  if (FORM_READY) persistNavigationSubview(target);
}
/**
 * syncCurrent  Synchronize the current browser state with related controls.
 * It belongs to the browser/MATLAB bridge path and must keep request payloads aligned with the MATLAB service contract.
 * Side effects: may send a request to the local MATLAB bridge and update browser-side UI state from the response.
 */
function nextNM2Revision(kind) {
  const now = Math.floor(Date.now() * 1000);
  if (kind === 'navigation') {
    NM2_NAV_REVISION = Math.max(NM2_NAV_REVISION + 1, now);
    return NM2_NAV_REVISION;
  }
  NM2_STATE_REVISION = Math.max(NM2_STATE_REVISION + 1, now);
  return NM2_STATE_REVISION;
}

function dataIOScopeKey() {
  const moduleKey = String(PARAMS.get('moduleKey') || '').toLowerCase();
  if (moduleKey === 'oocv_dataio') return 'oocv';
  if (moduleKey === 'dataio') return 'training';
  const tgt = matrixState && matrixState.importTarget && typeof matrixState.importTarget === 'object' ? matrixState.importTarget : {};
  return String(tgt.scope || '').toLowerCase();
}

const DATAIO_DERIVED_STATE_FIELDS = ['preview','persistedInspection','persistedQC','oocvScientificPolicy','existingCovariateNames','existingLabelAvailable','existingLabelColumns','oocvLabelsPresent'];

function stripDatabaseSecretsFromState(matrix) {
  if (!matrix || typeof matrix !== 'object') return matrix;
  if (Object.prototype.hasOwnProperty.call(matrix,'databasePassword')) delete matrix.databasePassword;
  const dbUrl = String(matrix.databaseUrl || '').trim();
  if (/^[A-Za-z][A-Za-z0-9+.-]*:\/\/[^/@]*:[^/@]*@/.test(dbUrl) || /(^|;)\s*(pwd|password)\s*=/i.test(dbUrl)) matrix.databaseUrl = '?';
  return matrix;
}

function dataIOStateForPersistence() {
  const current = matrixStateFromForm(false, false) || {};
  const clean = JSON.parse(JSON.stringify(current));
  DATAIO_DERIVED_STATE_FIELDS.forEach((k) => { if (Object.prototype.hasOwnProperty.call(clean,k)) delete clean[k]; });
  if (clean.matrix && typeof clean.matrix === 'object') {
    if (Object.prototype.hasOwnProperty.call(clean.matrix,'preview')) delete clean.matrix.preview;
    stripDatabaseSecretsFromState(clean.matrix);
  }
  const state = { scope: dataIOScopeKey(), matrixImport: clean };
  if (state.scope === 'oocv') {
    state.oocvDraft = {
      description: val('oocv_desc'),
      labelsKnown: checked('oocv_labels_known')
    };
  }
  return state;
}

function syncCurrent(force, failHard) {
  const state = dataIOStateForPersistence();
  const serialized = JSON.stringify(state);
  if (!force && serialized === NM2_LAST_DATAIO_JSON) return Promise.resolve({ ok: true, unchanged: true });
  const revision = nextNM2Revision('dataIO');
  return fetch(API('/api/nm2state'), {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ section: 'dataIO', revision, state })
  }).then(async (res) => {
    const out = await res.json().catch(() => ({}));
    if (!res.ok && !(out && out.stale)) throw new Error(out.message || `HTTP ${res.status}`);
    if (out && out.stale && Number(out.currentRevision || 0) > NM2_STATE_REVISION) NM2_STATE_REVISION = Number(out.currentRevision || 0);
    if (res.ok) NM2_LAST_DATAIO_JSON = serialized;
    return out;
  }).catch((err) => {
    setMessage(`Could not save the current DataIO settings: ${err.message || String(err)}`, 'danger');
    if (failHard) throw err;
    return { ok: false, error: err.message || String(err) };
  });
}

function persistNavigationSubview(subview) {
  const revision = nextNM2Revision('navigation');
  const ctx = appContext();
  let moduleKey = String(PARAMS.get('moduleKey') || '');
  if (!moduleKey) moduleKey = dataIOScopeKey() === 'oocv' ? 'oocv_dataio' : 'dataio';
  const navState = {
    subview: String(subview || ''),
    moduleKey,
    returnToWorkbench: !!ctx.returnToWorkbench,
    returnPage: String(ctx.returnPage || 'nm_workbench.html')
  };
  return fetch(API('/api/nm2state'), {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ section: 'navigation', revision, state: navState })
  }).then(async (res) => {
    const out = await res.json().catch(() => ({}));
    if (!res.ok && !(out && out.stale)) throw new Error(out.message || `HTTP ${res.status}`);
    if (out && out.stale && Number(out.currentRevision || 0) > NM2_NAV_REVISION) NM2_NAV_REVISION = Number(out.currentRevision || 0);
    return out;
  }).catch((err) => {
    setMessage(`Could not update the DataIO page state: ${err.message || String(err)}`, 'danger');
  });
}

function compatiblePersistedDataIOState(saved) {
  if (!saved || typeof saved !== 'object' || !saved.matrixImport || typeof saved.matrixImport !== 'object') return false;
  const savedScope = String(saved.scope || ((saved.matrixImport.importTarget || {}).scope) || '').toLowerCase();
  const currentScope = dataIOScopeKey();
  return !savedScope || !currentScope || savedScope === currentScope;
}

function restoreDataIOInputState(saved) {
  if (!compatiblePersistedDataIOState(saved)) return false;
  if (saved.oocvDraft && typeof saved.oocvDraft === 'object') {
    setVal('oocv_desc', saved.oocvDraft.description || '');
    const labelsKnownBox = document.getElementById('oocv_labels_known');
    if (labelsKnownBox) labelsKnownBox.checked = saved.oocvDraft.labelsKnown === true;
  }
  const fresh = matrixState && typeof matrixState === 'object' ? matrixState : {};
  const restored = JSON.parse(JSON.stringify(saved.matrixImport || {}));
  stripDatabaseSecretsFromState(restored.matrix);
  DATAIO_DERIVED_STATE_FIELDS.forEach((k) => {
    if (fresh[k] !== undefined) restored[k] = fresh[k];
  });
  if (fresh.matrix && fresh.matrix.preview !== undefined) {
    restored.matrix = restored.matrix && typeof restored.matrix === 'object' ? restored.matrix : {};
    restored.matrix.preview = fresh.matrix.preview;
  }
  matrixState = restored;
  STATE.matrixImport = matrixState;
  return true;
}

async function loadPersistedNavigationState() {
  try {
    const res = await fetch(API('/api/nm2state?section=navigation'), { cache: 'no-store' });
    if (!res.ok) return;
    const out = await res.json();
    NM2_NAV_REVISION = Math.max(NM2_NAV_REVISION, Number(out.revision || 0));
    if (out && out.state && typeof out.state === 'object') NM2_RECOVERY_SUBVIEW = String(out.state.subview || '');
  } catch (_) {}
}

async function loadPersistedDataIOState() {
  try {
    const res = await fetch(API('/api/nm2state?section=dataIO'), { cache: 'no-store' });
    if (res.status === 404) return false;
    const out = await res.json();
    if (!res.ok || !out || out.ok === false) throw new Error((out && out.message) || `HTTP ${res.status}`);
    NM2_STATE_REVISION = Math.max(NM2_STATE_REVISION, Number(out.revision || 0));
    if (!restoreDataIOInputState(out.state || {})) return false;
    // Do not project the still-unhydrated DOM back into STATE here.
    // initializeDataIOPage() renders matrixState into the form first and only then
    // establishes the persistence comparison baseline.
    return true;
  } catch (err) {
    setMessage(`Could not restore the saved DataIO settings: ${err.message || String(err)}`, 'danger');
    return false;
  }
}

async function adoptRecoveredDataIOState() {
  if (PARAMS.get('recovery') !== '1' || !hasImportTask()) return { ok: true, saved: false };

  // A cross-MATLAB recovery has the entered-but-uncommitted semantic input in
  // nm2_state.json, but the old in-process DataIO session-NM cache died with
  // MATLAB. Re-materialize that input once through the existing draft authority
  // before rendering the recovered page. Do not mutate the persisted browser
  // state merely to satisfy the draftDirty gate.
  const enteredState = JSON.parse(JSON.stringify(matrixState || {}));
  const draftState = JSON.parse(JSON.stringify(enteredState));
  draftState.draftDirty = true;
  draftState.importTarget = draftState.importTarget && typeof draftState.importTarget === 'object' ? draftState.importTarget : {};
  const scope = dataIOScopeKey();
  if (scope) draftState.importTarget.scope = scope;

  const res = await matlabService('dataio_save_draft', draftState, { timeout: 60 });
  if (!res || res.ok === false) {
    throw new Error(stripText(res, 'Could not restore the unfinished import from its saved settings.'));
  }
  if (!res.saved || !res.state || typeof res.state !== 'object') return res || { ok: true, saved: false };

  const backendState = res.state;
  const backendImport = backendState.matrixImport && typeof backendState.matrixImport === 'object' ? backendState.matrixImport : {};
  STATE = backendState;
  matrixState = enteredState;
  DATAIO_DERIVED_STATE_FIELDS.forEach((k) => { if (backendImport[k] !== undefined) matrixState[k] = backendImport[k]; });
  if (backendImport.matrix && backendImport.matrix.preview !== undefined) {
    matrixState.matrix = matrixState.matrix && typeof matrixState.matrix === 'object' ? matrixState.matrix : {};
    matrixState.matrix.preview = backendImport.matrix.preview;
  }
  matrixState.draftDirty = false;
  STATE.matrixImport = matrixState;
  FORM_DIRTY = false;
  return res;
}

function flushDataIOStateBeacon() {
  if (!FORM_READY) return;
  try {
    const state = dataIOStateForPersistence();
    const payload = JSON.stringify({ section: 'dataIO', revision: nextNM2Revision('dataIO'), state });
    const raw = API('/api/nm2state');
    const url = window.NMBridgeAuthenticatedURL ? window.NMBridgeAuthenticatedURL(raw) : raw;
    navigator.sendBeacon(url, new Blob([payload], { type: 'application/json' }));
  } catch (_) {}
}

/**
 * normalizeImageSpaceDefType  Normalize image space def type payloads into the browser-side model used by the UI.
 * It is a normalization helper that makes heterogeneous backend/browser values safe for downstream UI rendering.
 */
function normalizeImageSpaceDefType(v) {
  const s = String(v || 'brainmask').toLowerCase().replace(/-/g, '_');
  if (['atlas','roi','parcellation','parcellation_atlas'].includes(s)) return 'atlas';
  return 'brainmask';
}
/**
 * normalizeAtlasImportMode  Normalize atlas import mode payloads into the browser-side model used by the UI.
 * It is a normalization helper that makes heterogeneous backend/browser values safe for downstream UI rendering.
 */
function normalizeAtlasImportMode(v) {
  const s = String(v || 'voxelwise').toLowerCase().replace(/-/g, '_');
  if (['split','atlas_split','roi_split','split_modalities','voxelwise_split'].includes(s)) return 'split';
  if (['collapse','atlas_collapse','roi_collapse','roi_summary','summary'].includes(s)) return 'collapse';
  return 'voxelwise';
}
/**
 * normalizeAtlasCollapseMethod  Normalize atlas collapse method payloads into the browser-side model used by the UI.
 * It is a normalization helper that makes heterogeneous backend/browser values safe for downstream UI rendering.
 */
function normalizeAtlasCollapseMethod(v) {
  const s = String(v || 'soft_mean').toLowerCase().replace(/-/g, '_');
  if (['median','weighted_median','soft_median'].includes(s)) return 'soft_median';
  return 'soft_mean';
}

/**
 * setSelectOptions  Provide the set select options helper used by DataIO browser page for import configuration, preview, QC and commit operations.
 * It is a browser rendering helper: it updates DOM or SVG state from already retrieved NeuroMiner payloads and does not define new scientific results.
 * Side effects: updates DOM markup, CSS classes or control state for the active browser page.
 */
function setPromptSelectOptions(id, values, placeholder) {
  const el = document.getElementById(id);
  if (!el) return;
  const current = el.value;
  const opts = [`<option value="">${escapeHtml(placeholder || 'auto')}</option>`];
  arr(values).filter(Boolean).forEach((v) => opts.push(`<option value="${escapeHtml(v)}">${escapeHtml(v)}</option>`));
  el.innerHTML = opts.join('\n');
  if (current && arr(values).includes(current)) el.value = current;
}

/**
 * atlasDescriptorConfig  Provide the atlas descriptor config helper used by DataIO browser page for import configuration, preview, QC and commit operations.
 * It supports DataIO browser page for import configuration, preview, QC and commit operations at a local helper boundary rather than changing MATLAB-side NeuroMiner state.
 */
function atlasDescriptorConfig(kind) {
  if (kind === 'connectivity') {
    return {
      kind,
      label: 'Connectivity ROI description file',
      sourceAllowed: () => isConnectivitySource(),
      sourceWarn: 'Select Connectivity as the source type before editing ROI description settings.',
      atlasFileId: 'di_conn_atlas_file',
      descriptorFileId: 'di_conn_atlas_label_file',
      candidateId: 'di_conn_atlas_candidate_file',
      delimiterId: 'di_conn_atlas_label_delimiter',
      headerId: 'di_conn_atlas_label_header',
      idColumnId: 'di_conn_atlas_id_column',
      nameColumnId: 'di_conn_atlas_name_column',
      xColumnId: 'di_conn_atlas_x_column',
      yColumnId: 'di_conn_atlas_y_column',
      zColumnId: 'di_conn_atlas_z_column',
      statusId: 'connAtlasDescriptorStatus',
      previewId: 'connAtlasDescriptorPreview',
      atlasFilter: '*.nii;*.nii.gz;*.mat;*.mgz;*.mgh',
      descriptorFilter: '*.txt;*.csv;*.tsv;*.labels',
      noDescriptorText: 'No connectivity ROI description file has been checked.'
    };
  }
  return {
    kind: 'image',
    label: 'Atlas information',
    sourceAllowed: () => isImageSource() && normalizeImageSpaceDefType(val('di_image_space_type')) === 'atlas',
    sourceWarn: 'Select an atlas-based imaging source before editing ROI description settings.',
    atlasFileId: 'di_image_mask',
    descriptorFileId: 'di_image_atlas_label_file',
    candidateId: 'di_image_atlas_candidate_file',
    delimiterId: 'di_image_atlas_label_delimiter',
    headerId: 'di_image_atlas_label_header',
    idColumnId: 'di_image_atlas_id_column',
    nameColumnId: 'di_image_atlas_name_column',
    statusId: 'imageAtlasDescriptorStatus',
    previewId: 'imageAtlasDescriptorPreview',
    atlasFilter: '*.nii;*.nii.gz',
    descriptorFilter: '*.txt;*.csv;*.tsv;*.labels',
    noDescriptorText: 'No ROI description file has been checked.'
  };
}
/**
 * setAtlasDescriptorStatusFor  Provide the set atlas descriptor status for helper used by DataIO browser page for import configuration, preview, QC and commit operations.
 * It is a browser rendering helper: it updates DOM or SVG state from already retrieved NeuroMiner payloads and does not define new scientific results.
 * Side effects: updates DOM markup, CSS classes or control state for the active browser page.
 */
function setAtlasDescriptorStatusFor(kind, text, level) {
  const cfg = atlasDescriptorConfig(kind);
  const el = document.getElementById(cfg.statusId);
  if (!el) return;
  el.textContent = text || cfg.noDescriptorText;
  el.classList.remove('okText','warnText','dangerText','ok','warn','danger','info');
  if (level === 'ok') el.classList.add('okText');
  else if (level === 'danger') el.classList.add('dangerText');
  else if (level === 'warn') el.classList.add('warnText');
}
/**
 * atlasDescriptorLocalStatusForResult  Provide the atlas descriptor local status for result helper used by DataIO browser page for import configuration, preview, QC and commit operations.
 * It supports DataIO browser page for import configuration, preview, QC and commit operations at a local helper boundary rather than changing MATLAB-side NeuroMiner state.
 */
function atlasDescriptorLocalStatusForResult(res, kind) {
  if (kind === 'connectivity') {
    const coord = String((res && res.coordinateSummary && res.coordinateSummary.status) || '').toLowerCase();
    const loc = String((res && res.localizationSummary && res.localizationSummary.status) || '').toLowerCase();
    const atlas = String((res && res.atlasMatchSummary && res.atlasMatchSummary.status) || '').toLowerCase();
    const nRows = Number((res && res.coordinateSummary && res.coordinateSummary.nRows) || (res && res.nRows) || 0);
    const nValid = Number((res && res.coordinateSummary && res.coordinateSummary.nValid) || 0);
    const nLocalized = Number((res && res.localizationSummary && res.localizationSummary.nLocalized) || nValid);
    if (res && res.ok === false && atlas === 'none') {
      return { text: 'The labelled atlas and ROI description file have no matching ROI IDs. Import cannot continue.', level: 'danger' };
    }
    if (res && res.ok === false && atlas === 'unreadable') {
      return { text: 'Labelled atlas could not be inspected; import remains blocked. Open the header error icon for details.', level: 'danger' };
    }
    if (coord === 'full') {
      return { text: `Valid MNI coordinates were found for ${nValid}/${nRows} nodes in the ROI description file; no atlas image is required.`, level: 'ok' };
    }
    if (loc === 'full') {
      return { text: `All ${nLocalized}/${nRows} nodes have locations from the ROI description file or matching atlas labels.`, level: 'ok' };
    }
    if (loc === 'partial' || atlas === 'partial') {
      return { text: `Only ${nLocalized}/${nRows} nodes have spatial locations. NM2 will import only those nodes and their connecting edges.`, level: 'warn' };
    }
    return { text: `MNI coordinates established for ${nValid}/${nRows} nodes — select a labelled atlas fallback.`, level: 'warn' };
  }
  const status = res && res.matchSummary && res.matchSummary.status ? String(res.matchSummary.status).toLowerCase() : '';
  if (status === 'full') return { text: 'The ROI description file matches the atlas ROI IDs.', level: 'ok' };
  if (status === 'none') return { text: 'The ROI description file does not match the atlas ROI IDs. Check the message above for details.', level: 'danger' };
  if (status === 'partial') return { text: 'Only some ROI IDs in the description file match the atlas. Check the message above for details.', level: 'warn' };
  return { text: 'ROI description file checked. See the message above for details.', level: 'warn' };
}

/**
 * connectivityCoordinatesComplete  Return whether the inspected sidecar localizes every node directly in MNI space.
 */
function connectivityCoordinatesComplete() {
  return String((CONNECTIVITY_DESCRIPTOR_INSPECTION && CONNECTIVITY_DESCRIPTOR_INSPECTION.coordinateSummary && CONNECTIVITY_DESCRIPTOR_INSPECTION.coordinateSummary.status) || '').toLowerCase() === 'full';
}

/**
 * connectivityLocalizationBlocked  Return whether inspected sidecar/atlas correspondence is explicitly invalid.
 */
function connectivityLocalizationBlocked() {
  const res = CONNECTIVITY_DESCRIPTOR_INSPECTION;
  if (!res) return false;
  const atlasStatus = String((res.atlasMatchSummary && res.atlasMatchSummary.status) || '').toLowerCase();
  return res.ok === false && ['none','unreadable'].includes(atlasStatus);
}

/**
 * updateConnectivityAtlasFallbackState  Enable the labelled-atlas picker only when inspected sidecar coordinates are incomplete.
 */
function updateConnectivityAtlasFallbackState() {
  const active = isConnectivitySource();
  const hasSidecar = active && !!val('di_conn_atlas_label_file').trim();
  const inspected = hasSidecar && !!CONNECTIVITY_DESCRIPTOR_INSPECTION;
  const atlasRequired = inspected && !connectivityCoordinatesComplete();
  if (inspected && !atlasRequired && val('di_conn_atlas_file').trim()) {
    setVal('di_conn_atlas_file', '');
  }
  const atlasSelected = !!val('di_conn_atlas_file').trim();
  setDisabled('di_conn_atlas_file', !atlasRequired);
  setDisabled('pickConnAtlasFile', !atlasRequired);
  setDisabled('di_conn_atlas_candidate_file', !atlasRequired || !atlasSelected);
  setDisabled('detectConnAtlasDescriptor', !atlasRequired || !atlasSelected);
  setDisabled('inspectConnAtlasDescriptor', !hasSidecar);
  const field = document.getElementById('connAtlasFileField');
  if (field) {
    field.classList.toggle('disabledField', !atlasRequired);
    field.title = !hasSidecar ? 'Select and inspect the ROI description file first.' : (atlasRequired ? 'Some ROI coordinates are missing; select a labelled atlas image to locate the remaining ROIs.' : 'All nodes have valid MNI coordinates in the ROI description file; no atlas image is required.');
  }
}

/**
 * inspectConnectivityTableSchema  Resolve table row-name availability before asking for a case-ID variable.
 */
async function inspectConnectivityTableSchema(announce) {
  if (!isConnectivitySource() || connectivityInputFormat() !== 'table') {
    CONNECTIVITY_TABLE_SCHEMA = null;
    return null;
  }
  const tableVariable = val('di_conn_table_var').trim();
  const statusEl = document.getElementById('connTableCaseIDStatus');
  const selector = document.getElementById('di_conn_table_case_column');
  if (!tableVariable) {
    CONNECTIVITY_TABLE_SCHEMA = null;
    if (selector) {
      selector.innerHTML = '<option value="">Select a table first</option>';
      selector.disabled = true;
    }
    if (statusEl) statusEl.textContent = 'Select the connectivity table. MATLAB row names are inspected before any case-ID column is requested.';
    updateConnectivitySourceVisibility();
    updateActionButtons();
    return null;
  }
  try {
    if (statusEl) statusEl.textContent = 'Inspecting MATLAB table row names...';
    const res = await matlabService('dataio_connectivity_table_schema', {}, { tableVariable, timeout: 120 });
    CONNECTIVITY_TABLE_SCHEMA = res && res.ok !== false ? res : null;
    if (!CONNECTIVITY_TABLE_SCHEMA) {
      if (statusEl) statusEl.textContent = stripText(res, 'Connectivity table schema could not be inspected.');
      if (announce) setMessage(stripText(res, 'Connectivity table schema could not be inspected.'), 'danger');
      updateConnectivitySourceVisibility();
      updateActionButtons();
      return res;
    }
    const current = val('di_conn_table_case_column');
    if (res.rowNamesPresent) {
      if (selector) {
        selector.innerHTML = '<option value="">MATLAB table row names</option>';
        selector.value = '';
        selector.disabled = true;
      }
      setVal('di_conn_table_case_column', '');
      if (statusEl) statusEl.textContent = `Case IDs will be read from MATLAB table row names (${Number(res.nRows || 0)} rows). No separate Case-ID variable is needed; all ${Number(res.nVariables || 0)} table variables remain eligible connectivity features.`;
    } else {
      setPromptSelectOptions('di_conn_table_case_column', res.variableNames || [], 'Select case-ID variable');
      if (current && arr(res.variableNames).includes(current)) setVal('di_conn_table_case_column', current);
      if (selector) selector.disabled = false;
      if (statusEl) statusEl.textContent = 'The table has no row names. Select the Case-ID variable from this table. Text and cell-array columns are allowed; only the selected column is excluded from connectivity features.';
    }
    if (announce) setMessage(res.message || 'Connectivity table schema inspected.', 'info');
    invalidateMaterialization();
    matrixStateFromForm();
    updateConnectivitySourceVisibility();
    updateActionButtons();
    return res;
  } catch (err) {
    CONNECTIVITY_TABLE_SCHEMA = null;
    if (statusEl) statusEl.textContent = `Could not inspect the connectivity table columns: ${err.message || String(err)}`;
    if (announce) setMessage(`Could not inspect the connectivity table columns: ${err.message || String(err)}`, 'danger');
    updateConnectivitySourceVisibility();
    updateActionButtons();
    return null;
  }
}

/**
 * imageStateWithTopLevelFallback  Provide the image state with top level fallback helper used by DataIO browser page for import configuration, preview, QC and commit operations.
 * It supports DataIO browser page for import configuration, preview, QC and commit operations at a local helper boundary rather than changing MATLAB-side NeuroMiner state.
 */
function imageStateWithTopLevelFallback(st) {
  st = st || {};
  const img = Object.assign({}, st.image || {});
  const keys = [
    'imageFiles','files','PP','maskFile','brainmask','caseIDMode','caseIds','caseIDs',
    'auxiliarySourceType','auxiliaryAlignmentMode','auxiliaryVariableRoles','auxiliaryTableFiles',
    'labelMode','groupSizes','imageGroupSizes','groupNames','imageGroupNames',
    'classFileLists','labelNames','regressionLabelNames','labelNamesSource',
    'covariateNames','covmanage_edit','globalMode','globalSource',
    'globalUserSourceType','globalAlignmentMode','globalVariableRoles','globalTableFiles',
    'globalName','globnorm','threshop','threshval','threshlabels',
    'weightingFiles','spaceDefType','atlasImportMode','spaceDefImportMode','roiImportMode',
    'atlasCollapseMethod','collapseMethod','roiSummaryMethod','excludeSubjectZeros',
    'atlasLabelNames','atlasLabelFile','atlasDescriptorFile','atlasSidecarFile',
    'atlasLabelDelimiter','atlasLabelHasHeader','atlasLabelIDColumn','atlasLabelNameColumn',
    'atlasLabelDescriptor','atlasInfo',
    'surfaceImportMode','surfaceMode','surfaceSpaceMode','surfaceTemplate','surfaceTemplateSpace',
    'templateSpace','surfaceHemisphere','hemisphere','hemi','surfaceGeometryFile',
    'surfaceDisplayMeshFile','surfaceTemplateFile','geometryFile','surfaceInflatedGeometryFile',
    'inflatedSurfaceGeometryFile','surfaceInflatedTemplateFile'
  ];
  keys.forEach((k) => {
    if ((img[k] === undefined || img[k] === null || img[k] === '') && st[k] !== undefined && st[k] !== null && st[k] !== '') img[k] = st[k];
  });
  return img;
}
/**
 * renderAtlasDescriptorPreviewFor  Render the atlas descriptor preview for UI region from current browser state.
 * It is a browser rendering helper: it updates DOM or SVG state from already retrieved NeuroMiner payloads and does not define new scientific results.
 * Side effects: updates DOM markup, CSS classes or control state for the active browser page.
 */
function renderAtlasDescriptorPreviewFor(kind, desc) {
  const cfg = atlasDescriptorConfig(kind);
  const host = document.getElementById(cfg.previewId);
  if (!host) return;
  const rows = arr(desc && desc.previewRows).filter(Boolean);
  const columns = arr(desc && desc.columns).filter(Boolean);
  if (!rows.length || !columns.length) {
    host.hidden = true;
    host.innerHTML = '';
    return;
  }
  const showCols = columns.slice(0, 8);
  const head = showCols.map((c) => `<th>${escapeHtml(c)}</th>`).join('\n');
  const body = rows.slice(0, 8).map((r) => `<tr>${showCols.map((c) => `<td>${escapeHtml(r && r[c] !== undefined ? r[c] : '')}</td>`).join('\n')}</tr>`).join('\n');
  const idCol = (desc.defaultIDColumn || val(cfg.idColumnId) || 'auto');
  const nameCol = (desc.defaultNameColumn || val(cfg.nameColumnId) || 'auto');
  const coordText = kind === 'connectivity' ? `, MNI: ${escapeHtml((desc.defaultXColumn || val(cfg.xColumnId) || 'unresolved'))} / ${escapeHtml((desc.defaultYColumn || val(cfg.yColumnId) || 'unresolved'))} / ${escapeHtml((desc.defaultZColumn || val(cfg.zColumnId) || 'unresolved'))}` : '';
  host.innerHTML = `<div class="atlasDescriptorPreviewTitle">${kind === 'connectivity' ? 'ROI description file' : 'Atlas information'} preview — ROI-ID: ${escapeHtml(idCol)}, ROI-name: ${escapeHtml(nameCol)}${coordText}</div><div class="tableScroll"><table class="miniTable"><thead><tr>${head}</tr></thead><tbody>${body}</tbody></table></div>`;
  host.hidden = false;
}
/**
 * detectAtlasDescriptorCandidatesFor  Provide the detect atlas descriptor candidates for helper used by DataIO browser page for import configuration, preview, QC and commit operations.
 * It belongs to the browser/MATLAB bridge path and must keep request payloads aligned with the MATLAB service contract.
 * Side effects: may send a request to the local MATLAB bridge and update browser-side UI state from the response.
 */
async function detectAtlasDescriptorCandidatesFor(kind) {
  const cfg = atlasDescriptorConfig(kind);
  if (!cfg.sourceAllowed()) { setMessage(cfg.sourceWarn, 'warn'); return null; }
  const atlasFile = val(cfg.atlasFileId).trim();
  const sel = document.getElementById(cfg.candidateId);
  if (sel) sel.innerHTML = '<option value="">Detecting...</option>';
  if (!atlasFile) {
    const msg = kind === 'connectivity' ? 'Select a labelled atlas image before looking for an accompanying ROI description file.' : 'Select an atlas file before looking for an accompanying ROI description file.';
    setAtlasDescriptorStatusFor(kind, msg, 'warn');
    renderAtlasDescriptorPreviewFor(kind, null);
    setMessage(msg, 'warn');
    return null;
  }
  try {
    const res = await matlabService('dataio_atlas_descriptor_candidates', {}, { atlasFile, timeout: 120 });
    if (res && res.ok === false) {
      const msg = stripText(res, 'Could not inspect the selected atlas/ROI information file.');
      setAtlasDescriptorStatusFor(kind, 'Could not identify the columns in the selected atlas/ROI information file. See the message above.', 'danger');
      setMessage(msg, 'danger');
      return res;
    }
    const files = arr(res.files || res.candidates || res.paths || []).map((x) => typeof x === 'string' ? x : (x.file || x.path || x.name)).filter(Boolean);
    if (sel) {
      const opts = ['<option value="">No ROI description file selected</option>'].concat(files.map((f) => `<option value="${escapeHtml(f)}">${escapeHtml(f)}</option>`));
      sel.innerHTML = opts.join('\n');
    }
    if (res.status === 'single' && files.length === 1) {
      setVal(cfg.descriptorFileId, files[0]);
      setAtlasDescriptorStatusFor(kind, 'ROI description file detected automatically; inspecting columns...', 'ok');
      setMessage(res.message || `Atlas information auto-detected: ${files[0]}`, 'ok');
      await inspectAtlasDescriptorFor(kind, true);
    } else if (res.status === 'multiple') {
      const msg = res.message || 'Multiple possible ROI description files were found. Select one before Preview or Commit.';
      setAtlasDescriptorStatusFor(kind, 'Multiple possible ROI description files were found; select one to inspect.', 'warn');
      setMessage(msg, 'warn');
    } else {
      const msg = res.message || 'No accompanying ROI description file was found. ROI names will be generated unless you select one.';
      setAtlasDescriptorStatusFor(kind, 'No ROI description file detected automatically.', 'warn');
      setMessage(msg, 'warn');
    }
    invalidateMaterialization();
    matrixStateFromForm();
    return res;
  } catch (err) {
    const msg = `Could not inspect the selected atlas/ROI information file: ${err.message || String(err)}`;
    setAtlasDescriptorStatusFor(kind, 'Could not identify the columns in the selected atlas/ROI information file. See the message above.', 'danger');
    setMessage(msg, 'danger');
    return null;
  }
}
/**
 * inspectAtlasDescriptorFor  Provide the inspect atlas descriptor for helper used by DataIO browser page for import configuration, preview, QC and commit operations.
 * It belongs to the browser/MATLAB bridge path and must keep request payloads aligned with the MATLAB service contract.
 * Side effects: may send a request to the local MATLAB bridge and update browser-side UI state from the response.
 */
async function inspectAtlasDescriptorFor(kind, resetColumns) {
  const cfg = atlasDescriptorConfig(kind);
  if (!cfg.sourceAllowed()) { setMessage(cfg.sourceWarn, 'warn'); return null; }
  const atlasFile = val(cfg.atlasFileId).trim();
  const descriptorFile = val(cfg.descriptorFileId).trim() || val(cfg.candidateId);
  if (!descriptorFile) {
    const msg = kind === 'image' ? 'No ROI description file is selected. ROI names will be generated from atlas IDs.' : 'Select the ROI description file first.';
    setAtlasDescriptorStatusFor(kind, msg, 'warn');
    renderAtlasDescriptorPreviewFor(kind, null);
    setMessage(msg, 'warn');
    return null;
  }
  try {
    const extra = {
      kind,
      atlasFile,
      descriptorFile,
      delimiter: val(cfg.delimiterId) || 'auto',
      hasHeader: val(cfg.headerId) || 'auto',
      idColumn: resetColumns ? '' : (val(cfg.idColumnId) || ''),
      nameColumn: resetColumns ? '' : (val(cfg.nameColumnId) || ''),
      xColumn: kind === 'connectivity' && !resetColumns ? (val(cfg.xColumnId) || '') : '',
      yColumn: kind === 'connectivity' && !resetColumns ? (val(cfg.yColumnId) || '') : '',
      zColumn: kind === 'connectivity' && !resetColumns ? (val(cfg.zColumnId) || '') : '',
      timeout: 120
    };
    const res = await matlabService('dataio_atlas_descriptor_inspect', {}, extra);
    if (res && res.ok === false && !arr(res.columns).length) {
      const msg = stripText(res, 'Could not inspect the selected atlas/ROI information file.');
      setAtlasDescriptorStatusFor(kind, 'Could not inspect the selected atlas/ROI information file. See the message above.', 'danger');
      renderAtlasDescriptorPreviewFor(kind, null);
      setMessage(msg, 'danger');
      return res;
    }
    if (kind === 'image') ATLAS_DESCRIPTOR_INSPECTION = res;
    if (kind === 'connectivity') CONNECTIVITY_DESCRIPTOR_INSPECTION = res;
    renderAtlasDescriptorPreviewFor(kind, res);
    if (res.delimiter) setVal(cfg.delimiterId, res.delimiter);
    setVal(cfg.headerId, res.hasHeader === true ? 'yes' : (res.hasHeader === false ? 'no' : 'auto'));
    setPromptSelectOptions(cfg.idColumnId, res.candidateIDColumns || res.columns || [], 'auto');
    setPromptSelectOptions(cfg.nameColumnId, res.candidateNameColumns || res.columns || [], 'auto');
    if (res.defaultIDColumn) setVal(cfg.idColumnId, res.defaultIDColumn);
    if (res.defaultNameColumn) setVal(cfg.nameColumnId, res.defaultNameColumn);
    if (kind === 'connectivity') {
      const allColumns = arr(res.columns).filter(Boolean);
      const coordinateOptions = (candidates) => Array.from(new Set(arr(candidates).filter(Boolean).concat(allColumns)));
      setPromptSelectOptions(cfg.xColumnId, coordinateOptions(res.candidateXColumns), 'auto');
      setPromptSelectOptions(cfg.yColumnId, coordinateOptions(res.candidateYColumns), 'auto');
      setPromptSelectOptions(cfg.zColumnId, coordinateOptions(res.candidateZColumns), 'auto');
      if (res.defaultXColumn) setVal(cfg.xColumnId, res.defaultXColumn);
      if (res.defaultYColumn) setVal(cfg.yColumnId, res.defaultYColumn);
      if (res.defaultZColumn) setVal(cfg.zColumnId, res.defaultZColumn);
    }
    const status = kind === 'connectivity' ? String((res.localizationSummary && res.localizationSummary.status) || (res.coordinateSummary && res.coordinateSummary.status) || '') : (res.matchSummary && res.matchSummary.status ? res.matchSummary.status : '');
    const msg = res.message || (kind === 'connectivity' ? 'ROI description file inspected.' : 'Atlas information inspected.');
    const local = atlasDescriptorLocalStatusForResult(res, kind);
    setAtlasDescriptorStatusFor(kind, local.text, local.level);
    setMessage(msg, status === 'full' ? 'ok' : (status === 'none' && res.ok === false ? 'danger' : 'warn'));
    if (kind === 'connectivity') updateConnectivityAtlasFallbackState();
    invalidateMaterialization();
    matrixStateFromForm();
    return res;
  } catch (err) {
    const msg = `Could not inspect the selected atlas/ROI information file: ${err.message || String(err)}`;
    setAtlasDescriptorStatusFor(kind, 'Could not inspect the selected atlas/ROI information file. See the message above.', 'danger');
    renderAtlasDescriptorPreviewFor(kind, null);
    setMessage(msg, 'danger');
    return null;
  }
}
/**
 * pickAtlasDescriptorFileFor  Provide the pick atlas descriptor file for helper used by DataIO browser page for import configuration, preview, QC and commit operations.
 * It belongs to the browser/MATLAB bridge path and must keep request payloads aligned with the MATLAB service contract.
 * Side effects: may send a request to the local MATLAB bridge and update browser-side UI state from the response.
 */
async function pickAtlasDescriptorFileFor(kind) {
  const cfg = atlasDescriptorConfig(kind);
  if (!cfg.sourceAllowed()) { setMessage(cfg.sourceWarn, 'warn'); return; }
  try {
    const pick = await fetch(API('/api/pickpath'), { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ kind: 'file', multiple: false, filter: cfg.descriptorFilter, timeout: 240 }) }).then((r) => r.json());
    const files = arr(pick.paths || pick.files || pick.path || pick.file).filter(Boolean);
    if (!files.length) return;
    setVal(cfg.descriptorFileId, files[0]);
    await inspectAtlasDescriptorFor(kind, true);
    invalidateMaterialization();
    matrixStateFromForm();
  } catch (err) {
    setMessage(`Could not select the atlas/ROI information file: ${err.message || String(err)}`, 'danger');
  }
}
/**
 * pickAtlasFileFor  Provide the pick atlas file for helper used by DataIO browser page for import configuration, preview, QC and commit operations.
 * It belongs to the browser/MATLAB bridge path and must keep request payloads aligned with the MATLAB service contract.
 * Side effects: may send a request to the local MATLAB bridge and update browser-side UI state from the response.
 */
async function pickAtlasFileFor(kind) {
  const cfg = atlasDescriptorConfig(kind);
  if (kind !== 'connectivity') return;
  if (!isConnectivitySource()) { setMessage(cfg.sourceWarn, 'warn'); return; }
  try {
    const pick = await fetch(API('/api/pickpath'), { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ kind: 'file', multiple: false, filter: cfg.atlasFilter, timeout: 240 }) }).then((r) => r.json());
    const files = arr(pick.paths || pick.files || pick.path || pick.file).filter(Boolean);
    if (!files.length) return;
    setVal(cfg.atlasFileId, files[0]);
    if (kind === 'connectivity' && val(cfg.descriptorFileId).trim()) await inspectAtlasDescriptorFor(kind, false);
    else await detectAtlasDescriptorCandidatesFor(kind);
    invalidateMaterialization();
    matrixStateFromForm();
  } catch (err) {
    setMessage(`Could not select the labelled connectivity atlas: ${err.message || String(err)}`, 'danger');
  }
}

/**
 * qcSequentialRgb  Provide the qc sequential rgb helper used by DataIO browser page for import configuration, preview, QC and commit operations.
 * It supports DataIO browser page for import configuration, preview, QC and commit operations at a local helper boundary rather than changing MATLAB-side NeuroMiner state.
 */
const QC_SEQUENTIAL_STOPS = [
  [248, 250, 252],
  [255, 209, 102],
  [232, 93, 4]
];
const QC_HYBRID_NEGATIVE_STOPS = [[40, 200, 232], [39, 93, 241], [139, 16, 232]];
const QC_HYBRID_POSITIVE_STOPS = [[255, 223, 89], [255, 140, 34], [223, 22, 45]];
const QC_BIPOLAR_GRADIENT = 'linear-gradient(90deg, #40a0ff 0%, #e5e7eb 50%, #ff5050 100%)';
const qcRgbInterpolate = window.NMImageSliceViewer.rgbInterpolate;
const qcGroupTone = window.NMImageSliceViewer.groupTone;
const qcGroupGradient = window.NMImageSliceViewer.groupGradient;
const qcGroupMatrixRgb = window.NMImageSliceViewer.groupMatrixRgb;
function qcSequentialRgb(t) {
  const x = Math.max(0, Math.min(1, Number(t) || 0));
  const index = x < 0.5 ? 0 : 1;
  const weight = index === 0 ? x / 0.5 : (x - 0.5) / 0.5;
  return qcRgbInterpolate(QC_SEQUENTIAL_STOPS, index, weight);
}

/** Resolve sequential versus bipolar display semantics from the materialized finite payload. */
function qcDisplaySemantics(overlayKind, windowVals, values, metricKey = '') {
  const kind = String(overlayKind || 'sequential');
  const win = arr(windowVals).map((x) => Number(x));
  const group = metricKey === 'feature_mean' || metricKey === 'feature_std';
  if (kind !== 'sequential' && !group) return { kind, window: win };
  let minValue = Infinity; let maxValue = -Infinity;
  const step = group ? Math.max(1, Math.ceil(values.length / 65536)) : 0;
  const sample = [];
  for (let i = 0; i < values.length; i += 1) {
    const value = Number(values[i]);
    if (!Number.isFinite(value)) continue;
    if (value < minValue) minValue = value;
    if (value > maxValue) maxValue = value;
    if (step && i % step === 0) sample.push(value);
  }
  const signed = kind === 'bipolar' || (minValue < 0 && (metricKey === 'feature_mean' || maxValue > 0));
  if (group && sample.length) {
    if (signed) for (let i = 0; i < sample.length; i += 1) sample[i] = Math.abs(sample[i]);
    sample.sort((a, b) => a - b);
    const upper = Math.max(quantileSorted(sample, 0.99), 1e-6);
    if (signed) return { kind: 'bipolar', window: [-upper, upper] };
    return { kind, window: [metricKey === 'feature_std' ? 0 : quantileSorted(sample, 0.01), upper] };
  }
  if (!signed) return { kind, window: win };
  const bound = Math.max(Math.abs(minValue), Math.abs(maxValue));
  return { kind: 'bipolar', window: [-bound, bound] };
}

/**
 * hslToRgb  Provide the hsl to rgb helper used by DataIO browser page for import configuration, preview, QC and commit operations.
 * It supports DataIO browser page for import configuration, preview, QC and commit operations at a local helper boundary rather than changing MATLAB-side NeuroMiner state.
 */
function hslToRgb(h, s, l) {
  h = ((Number(h) % 360) + 360) % 360; s = Math.max(0, Math.min(1, Number(s))); l = Math.max(0, Math.min(1, Number(l)));
  const c = (1 - Math.abs(2 * l - 1)) * s;
  const x = c * (1 - Math.abs((h / 60) % 2 - 1));
  const m = l - c / 2;
  let r = 0, g = 0, b = 0;
  if (h < 60) { r = c; g = x; } else if (h < 120) { r = x; g = c; } else if (h < 180) { g = c; b = x; } else if (h < 240) { g = x; b = c; } else if (h < 300) { r = x; b = c; } else { r = c; b = x; }
  return [Math.round((r + m) * 255), Math.round((g + m) * 255), Math.round((b + m) * 255)];
}
/**
 * updateAtlasHoverFromCanvas  Update atlas hover from canvas state or markup after user interaction or bridge refresh.
 * It supports DataIO browser page for import configuration, preview, QC and commit operations at a local helper boundary rather than changing MATLAB-side NeuroMiner state.
 */
function updateAtlasHoverFromCanvas(evt) {
  const v = IMAGE_VIEWER_VOLUME;
  if (!v || v.overlayMode !== 'atlas' || !v.maskData) return;
  const canvas = document.getElementById('ivCanvas');
  const msg = document.getElementById('ivMessage');
  if (!canvas || !msg) return;
  const rect = canvas.getBoundingClientRect();
  const x = Math.floor((evt.clientX - rect.left) * (v.dims[1] / Math.max(1, rect.width)));
  const y = Math.floor((evt.clientY - rect.top) * (v.dims[0] / Math.max(1, rect.height)));
  if (x < 0 || y < 0 || x >= v.dims[1] || y >= v.dims[0]) return;
  const slice = Math.max(1, Math.min(v.dims[2], Number(IMAGE_VIEWER_SLICE || 1)));
  const idx = (slice - 1) * v.dims[0] * v.dims[1] + y + x * v.dims[0];
  const roi = Number(v.maskData[idx] || 0);
  if (Number.isFinite(roi) && roi !== 0) {
    const name = (v.roiLabels && (v.roiLabels[`roi_${roi}`] || v.roiLabels[String(roi)])) || `ROI_${roi}`;
    const qc = imageViewerVoxelQCValue(x, y, slice - 1);
    msg.textContent = Number.isFinite(qc) && imageViewerActiveOverlay()
      ? `Atlas ROI under cursor: ${roi} — ${name}; ${imageViewerActiveOverlay().metricLabel || 'QC'} = ${formatCell(qc)}`
      : `Atlas ROI under cursor: ${roi} — ${name}`;
  }
}
