/**
 * applyConnectivitySubspaceSelectorFromModal  Apply the connectivity subspace selector from modal change to local browser state or visible controls.
 * It supports DataIO browser page for import configuration, preview, QC and commit operations at a local helper boundary rather than changing MATLAB-side NeuroMiner state.
 */
function applyConnectivitySubspaceSelectorFromModal() {
  const nodes = connSelectorNodes();
  const all = nodes.map((n) => n.pos);
  const source = CONN_SELECTOR_STATE.source.slice().sort((a,b) => a - b);
  const target = CONN_SELECTOR_STATE.target.slice().sort((a,b) => a - b);
  if (!source.length || !target.length) {
    const stat = document.getElementById('connSelectorStatus');
    if (stat) stat.textContent = 'Cannot apply: source and target lists must both contain at least one node.';
    return;
  }
  const full = source.length === all.length && target.length === all.length && source.every((p,i) => p === all[i]) && target.every((p,i) => p === all[i]);
  setConnectivitySubspaceEnabled(!full);
  setVal('di_conn_subspace_mode', 'between');
  setVal('di_conn_subspace_set_a', source.map(connSelectorNodeLabel).join('\n'));
  setVal('di_conn_subspace_set_b', target.map(connSelectorNodeLabel).join('\n'));
  setVal('di_conn_subspace_seed_nodes', '');
  setVal('di_conn_subspace_metadata_column', '');
  setVal('di_conn_subspace_metadata_values', '');
  setVal('di_conn_subspace_metadata_edge_mode', 'involving');
  closeConnectivitySubspaceSelector();
  applyConnectivitySubspaceSelectionSettings();
}

