function sourceIsReadyForVariables() {
  if (!sourceVariableListingVisible()) return false;
  if (sourceType() === 'matfile') return lineList(val('di_medit')).length > 0;
  if (sourceType() === 'database') {
    if (!databaseConnectionReady() || !databaseConnectorAvailable(val('di_db_connector'))) return false;
    if (databaseUsesQuery()) return databaseDatabaseReady() && !!val('di_db_query').trim();
    return databaseNamespaceSessionReadyForTables();
  }
  return true;
}

