/**
 * databaseConnectorKey  Resolve the database connector key identifier used to connect UI state with NeuroMiner payload metadata.
 * It supports DataIO browser page for import configuration, preview, QC and commit operations at a local helper boundary rather than changing MATLAB-side NeuroMiner state.
 */
function databaseConnectorKey(connector) {
  const c = String(connector || '').toLowerCase();
  if (['sqlite', 'sqlite_file', 'sqlitefile'].includes(c)) return 'sqlite_file';
  if (['postgres', 'postgresql'].includes(c)) return 'postgresql';
  if (['mysql', 'mariadb', 'mysql_mariadb'].includes(c)) return 'mysql';
  if (['odbc', 'odbc_dsn', 'dsn'].includes(c)) return 'odbc_dsn';
  if (['jdbc', 'jdbc_url'].includes(c)) return 'jdbc_url';
  return c;
}
