  const objectId = globalMode ? 'di_image_global_object' : 'di_image_aux_object';
  const path = val(fileId).trim();
  if (!path) { setMessage(`Select the ${globalMode ? 'global' : 'auxiliary'} CSV/spreadsheet file first.`, 'warn'); return null; }
