  if (metadataSectionTitle) metadataSectionTitle.textContent = explicitLabels ? 'Labels and covariates' : 'Covariates';
  if (metadataIntro) metadataIntro.textContent = explicitLabels
    ? 'Provide labels from the MATLAB workspace or a CSV/spreadsheet and align them to the modality cases. Covariates are optional. Configure global values separately where supported.'
    : 'Select None when no covariates are needed, or select a covariate source and align it to the modality cases. Configure global values separately where supported.';
