/**
 * requiredRolesAssigned  Provide the required roles assigned helper used by DataIO browser page for import configuration, preview, QC and commit operations.
 * It supports DataIO browser page for import configuration, preview, QC and commit operations at a local helper boundary rather than changing MATLAB-side NeuroMiner state.
 */
function requiredRolesAssigned() {
  const st = sourceType();
  if (st === 'image-list' || st === 'surface-list') return imageBasicSourceReady() && imageLabelsReadyForCommit();
  if (st === 'connectivity') return connectivitySourceReady();
  if (st === 'workspace' || st === 'matfile' || st === 'tablefile' || st === 'tablevar' || st === 'database') {
    const roles = currentVariableRoles();
    const align = val('di_variable_alignment') || 'key_per_block';
    const headerNamedTabular = ['tablefile','tablevar'].includes(st) || st === 'database';
    if (!roles.features.length || (!headerNamedTabular && !featureNameAssignmentsComplete(roles))) return false;
    if ((oocvAutomaticFeatureMappingActive() || oocvManualFeatureMappingActive()) && arr(OOCV_FEATURE_CORRESPONDENCE.ambiguousColumns).length) return false;
    if (oocvManualFeatureMappingActive() && arr(OOCV_FEATURE_CORRESPONDENCE.invalidTargetIndices).length) return false;
    if (labelsAllowedForCurrentImport() && !roles.labels.length) return false;
    if (!headerNamedTabular && roles.covariates.length && !roles.covariateNames.length && !commaList(val('di_var_covarnames_manual')).length) return false;
    if (align === 'row_order') return roles.caseId.length === 1;
    const rowBlocks = [].concat(roles.features, labelsAllowedForCurrentImport() ? roles.labels : [], roles.covariates);
    return rowBlocks.length > 0 && rowBlocks.every((ref) => variableRoleCaseRefs(ref).length > 0);
  }
  return false;
}
/**
 * invalidReasonForAction  Provide the invalid reason for action helper used by DataIO browser page for import configuration, preview, QC and commit operations.
 * It supports DataIO browser page for import configuration, preview, QC and commit operations at a local helper boundary rather than changing MATLAB-side NeuroMiner state.
 */
function invalidReasonForAction(action) {
  const st = sourceType();
  const importActions = ['listVariables', 'headers', 'refreshTableCache', 'preview', 'commit', 'pickFile'];
  if (importActions.includes(action) && !hasImportTask()) return dataIOMode() === 'training_import' ? 'No active import task. Start with Add, Replace, or Resume on the Overview page.' : 'No active import task. Training data are finalized; use OOCV/application import only in application mode.';
  if (action === 'pickFile') {
    if (st !== 'matfile' && st !== 'tablefile' && st !== 'image-list' && st !== 'surface-list' && st !== 'connectivity' && st !== 'roi') return 'File picking is only available for MAT-file, text/spreadsheet table, connectivity, ROI, imaging, and surface sources.';
    return '';
  }
  if (action === 'listVariables') {
    if (!sourceIsReadyForVariables()) {
      if (sourceType() === 'matfile') return 'Add at least one MAT-file before refreshing its variable list.';
      if (sourceType() === 'database' && !databaseUsesQuery() && databaseNamespaceReadyForTables() && !databaseNamespaceSessionReadyForTables()) return 'Re-enter the password if required, then list the database and schema again before refreshing tables.';
      return 'Source variables are not available.';
    }
    return '';
  }
  if (action === 'headers') {
    if (st === 'database' && !databaseConnectorAvailable(val('di_db_connector'))) return databaseCapabilityText();
    if (!sourceIsReadyForHeaders()) return st === 'database' ? 'Select a database connector/source and either a table/view or a custom SQL query before probing columns.' : 'Select a table file or one or more MATLAB table variables before probing headers.';
    return '';
  }
  if (action === 'refreshTableCache') {
    if (!['tablefile','database'].includes(st)) return 'Table-source reload is only needed for text/spreadsheet or database sources.';
    return '';
  }
  if (action === 'preview' || action === 'commit') {
    if (st === 'tablefile' && tableFileSourcesNeedRefresh()) return 'The table-file list changed. Refresh data sources before Preview or Commit.';
    if (action === 'commit' && PREVIEW_REQUIRED_AFTER_INVALIDATION) return 'The import inputs changed after Preview. Run Preview again before Commit.';
    if (st === 'database' && !databaseConnectorAvailable(val('di_db_connector'))) return databaseCapabilityText();
    if (st === 'image-list' || st === 'surface-list') return imageRequirementReason(action === 'commit');
    if (st === 'connectivity') return connectivityRequirementReason();
    if (st === 'roi') return roiRequirementReason();
    if (!requiredRolesAssigned()) {
      if ((oocvAutomaticFeatureMappingActive() || oocvManualFeatureMappingActive()) && arr(OOCV_FEATURE_CORRESPONDENCE.ambiguousColumns).length) {
        const prefix = oocvManualFeatureMappingActive() ? 'Manual' : 'Automatic';
        return `${prefix} OOCV feature correspondence is ambiguous for: ${arr(OOCV_FEATURE_CORRESPONDENCE.ambiguousColumns).join(', ')}. Resolve the conflicting assignment before Preview.`;
      }
      if (oocvManualFeatureMappingActive() && arr(OOCV_FEATURE_CORRESPONDENCE.invalidTargetIndices).length) return 'One or more saved manual OOCV feature assignments refer to source variables that are no longer available. Repair or clear the invalid assignment before Preview.';
      if (['workspace','matfile','tablefile','tablevar'].includes(st) || st === 'database') return (['tablefile','tablevar'].includes(st) || st === 'database') ? ((oocvAutomaticFeatureMappingActive() || oocvManualFeatureMappingActive()) ? 'OOCV feature correspondence requires at least one assigned training feature; assign required labels and define a key for each included source block.' : 'Assign feature variables and the required labels, then define a key for each row-bearing variable or explicitly assert row order.') : 'Assign every required input and select one feature-name variable for each feature input. Labels are required for the first labelled modality; covariates also require names.';
      return 'Assign exactly one case-ID source and at least one feature source. Labels are required only for the first modality.';
    }
    if (action === 'commit' && ['workspace','matfile','tablefile','tablevar','database'].includes(st)) {
      const desc = String(val('di_desc') || '').trim();
      if (!desc || desc === '?') return 'Add a concise modality description before committing the import.';
    }
    return '';
  }
  return '';
}
/**
 * mandatoryElementActive  Return whether a mandatory-state target is currently user-actionable.
 * Hidden or disabled controls are deliberately neutral: mandatory styling is navigation only
 * and must not imply that a locked OOCV/scientific field can be edited locally.
 */
function mandatoryElementActive(el) {
  if (!el) return false;
  let node = el;
  while (node && node !== document.body) {
    if (node.hidden || node.style.display === 'none') return false;
    node = node.parentElement;
  }
  if ('disabled' in el && el.disabled) return false;
  return true;
}
/** Apply one red/green mandatory-state projection without changing action eligibility. */
function setMandatoryFieldState(id, required, complete, reason) {
  const el = document.getElementById(id);
  if (!el || !['INPUT','SELECT','TEXTAREA','BUTTON'].includes(el.tagName)) return;
  el.classList.remove('nmMandatoryMissing','nmMandatoryComplete');
  el.removeAttribute('aria-required');
  el.removeAttribute('aria-invalid');
  el.removeAttribute('data-mandatory-reason');
  if (!required || !mandatoryElementActive(el)) return;
  el.classList.add(complete ? 'nmMandatoryComplete' : 'nmMandatoryMissing');
  el.setAttribute('aria-required','true');
  el.setAttribute('aria-invalid',complete ? 'false' : 'true');
  if (!complete && reason) el.setAttribute('data-mandatory-reason',String(reason));
}
/**
 * updateMandatoryFieldNavigation  Project the existing DataIO readiness contract onto visible controls.
 * This function never gates Preview/Commit and never defines scientific validity; action eligibility
 * remains owned by invalidReasonForAction and the source-specific requirement authorities above.
 */
function markSharedAuxiliaryReadiness(mark) {
  const ctx = sharedImportDefinitionContext();
  if (!ctx.active) return;
  const auxSource = normalizeImageAuxSourceType(val('di_image_aux_source'));
  const labelCount = auxSource === 'none' ? 0 : (auxSource === 'workspace' ? (val('di_image_labels').trim() ? 1 : 0) : selectedValues('di_image_aux_label_columns').length);
  const covariateCount = auxSource === 'none' ? 0 : (auxSource === 'workspace' ? (val('di_image_covariates').trim() ? 1 : 0) : optionValues('di_image_aux_covariate_assigned').length);
  const labelsRequired = sharedAuxiliaryLabelsRequireSource();
  const covariatesRequired = !labelsRequired && auxSource !== 'none';
  const caseMapped = auxSource !== 'none' && normalizeImageMetadataAlignment(val('di_image_metadata_alignment')) === 'case_id';
  mark('di_image_aux_source', labelsRequired, auxSource !== 'none', 'Select the source used to define labels.');
  if (auxSource === 'workspace') {
    mark('di_image_labels', labelsRequired, labelCount > 0, 'Select the required label variable.');
    mark('di_image_label_case_ids', caseMapped && labelsRequired && labelCount > 0, !!val('di_image_label_case_ids').trim(), 'Case-ID matching requires label Case-IDs.');
    mark('di_image_covariates', covariatesRequired, covariateCount > 0, 'Select a covariate variable or select Source = None.');
    mark('di_image_covariate_case_ids', caseMapped && covariateCount > 0, !!val('di_image_covariate_case_ids').trim(), 'Case-ID matching requires covariate Case-IDs.');
  } else if (auxSource === 'tablefile') {
    const path = val('di_image_aux_file').trim();
    const resolved = arr(IMAGE_AUX_SOURCE_VARIABLES).filter((ref) => String((ref || {}).sourcePath || '').trim() === path);
    const object = val('di_image_aux_object');
    mark('di_image_aux_file', true, !!path && resolved.length > 0, 'Select and resolve the CSV/spreadsheet label, covariate or global-value source file.');
    mark('di_image_aux_object', true, !!object && resolved.some((ref) => imageTableObjectToken(ref) === object), 'Select a table / sheet/sheet from the resolved label/covariate/global-value file.');
    mark('di_image_aux_label_columns', labelsRequired, labelCount > 0 && (imageModeflag() !== 'classification' || labelCount === 1), imageModeflag() === 'classification' ? 'Select exactly one classification label column.' : 'Select one or more regression target columns.');
    mark('di_image_aux_key_assigned', caseMapped, optionValues('di_image_aux_key_assigned').length > 0, 'Case-ID matching requires at least one selected Case-ID column.');
    mark('di_image_aux_covariate_assigned', covariatesRequired || covariateCount > 0, covariateCount > 0, 'Add at least one covariate column.');
  }
  const globalsOn = ctx.globalsSupported && normalizeImageGlobalMode(val('di_image_global_mode')) !== 'none';
  const userGlobals = globalsOn && normalizeImageGlobalSource(val('di_image_global_source')) === 'user';
  const globalSource = normalizeImageAuxSourceType(val('di_image_global_user_source'));
  const globalCaseMapped = normalizeImageMetadataAlignment(val('di_image_global_alignment')) === 'case_id';
  if (globalSource === 'workspace') {
    mark('di_image_globals', userGlobals, !!val('di_image_globals').trim(), 'The selected global mode requires a global variable.');
    mark('di_image_global_case_ids', globalCaseMapped && userGlobals && !!val('di_image_globals').trim(), !!val('di_image_global_case_ids').trim(), 'Case-ID global alignment requires global Case-IDs.');
  } else {
    const path = val('di_image_global_file').trim();
    const resolved = arr(IMAGE_GLOBAL_SOURCE_VARIABLES).filter((ref) => String((ref || {}).sourcePath || '').trim() === path);
    const object = val('di_image_global_object');
    mark('di_image_global_file', userGlobals, !!path && resolved.length > 0, 'Select and resolve the global CSV/spreadsheet file.');
    mark('di_image_global_object', userGlobals, !!object && resolved.some((ref) => imageTableObjectToken(ref) === object), 'Select a table / sheet/sheet from the resolved global file.');
    mark('di_image_global_assigned', userGlobals, optionValues('di_image_global_assigned').length === 1, 'Add exactly one global column.');
    mark('di_image_global_key_assigned', globalCaseMapped && userGlobals, optionValues('di_image_global_key_assigned').length > 0, 'Case-ID global alignment requires at least one selected Case-ID column.');
  }
}

function updateMandatoryFieldNavigation() {
  document.querySelectorAll('.nmMandatoryMissing,.nmMandatoryComplete').forEach((el) => {
    el.classList.remove('nmMandatoryMissing','nmMandatoryComplete');
    el.removeAttribute('aria-required'); el.removeAttribute('aria-invalid'); el.removeAttribute('data-mandatory-reason');
  });
  if (!hasImportTask()) return;
  const st = sourceType();
  const mark = (id, required, complete, reason) => setMandatoryFieldState(id, !!required, !!complete, reason || 'Required information is incomplete.');
  mark('di_source_type', true, !!st, 'Select a data source type.');
  if (taskFrameworkEditable()) mark('di_modeflag', true, !!val('di_modeflag'), 'Select classification or regression.');

  if (['workspace','matfile','tablefile','tablevar','database'].includes(st)) {
    const roles = currentVariableRoles();
    const align = val('di_variable_alignment') || 'key_per_block';
    const headerNamed = ['tablefile','tablevar'].includes(st) || st === 'database';
    const needsLabels = labelsAllowedForCurrentImport();
    const featureKeysOK = align !== 'key_per_block' || arr(roles.features).every((ref) => variableRoleCaseRefs(ref).length > 0);
    const labelKeysOK = align !== 'key_per_block' || arr(roles.labels).every((ref) => variableRoleCaseRefs(ref).length > 0);
    const covariateKeysOK = align !== 'key_per_block' || arr(roles.covariates).every((ref) => variableRoleCaseRefs(ref).length > 0);
    mark('di_desc', true, !!String(val('di_desc') || '').trim() && String(val('di_desc') || '').trim() !== '?', 'A modality description is required for Commit.');
    if (st === 'matfile') mark('di_medit', true, lineList(val('di_medit')).length > 0, 'Add at least one MAT-file.');
    if (st === 'tablefile') {
      const tableInventoryReady = lineList(val('di_table_file')).length > 0 && !tableFileSourcesNeedRefresh();
      mark('di_table_file', true, tableInventoryReady, 'Add table file(s) and refresh their tables / sheets.');
      mark('di_sheet_included', tableInventoryReady, selectedSheetNames().length > 0, 'Add at least one table / sheet to Included tables.');
    }
    if (st === 'tablevar') {
      const tableVariablesReady = assignedTableVariables().length > 0;
      mark('di_tablevar_select', true, tableVariablesReady, 'Add at least one MATLAB table source.');
      mark('di_sheet_included', tableVariablesReady, selectedSheetNames().length > 0, 'Add at least one MATLAB table to Included tables.');
    }
    if (st === 'database') {
      const connector = databaseConnectorKey(val('di_db_connector') || 'sqlite_file');
      const hierarchy = databaseConnectorHierarchy(connector);
      const databaseChoicesLoaded = !hierarchy.includes('database') || DATABASE_NAMESPACE_LISTED.database;
      const schemaChoicesLoaded = !hierarchy.includes('schema') || DATABASE_NAMESPACE_LISTED.schema;
      const databaseSelected = !!val('di_db_database');
      const schemaSelected = !!val('di_db_schema');
      const namespaceSessionReady = (!hierarchy.includes('database') || (databaseChoicesLoaded && databaseSelected)) && (!hierarchy.includes('schema') || (schemaChoicesLoaded && schemaSelected));
      mark('di_db_connector', true, databaseConnectorAvailable(connector), databaseCapabilityText());
      mark(connector === 'sqlite_file' ? 'di_db_file' : 'di_db_url', true, databaseConnectionReady(), 'Provide the database connection source.');
      if (hierarchy.includes('database')) {
        mark('listDatabaseNamespaces', !databaseChoicesLoaded, false, 'List the available databases.');
        mark('di_db_database', databaseChoicesLoaded, databaseSelected, 'Select a database.');
      }
      if (hierarchy.includes('schema')) {
        mark('listDatabaseSchemas', databaseSelected && !schemaChoicesLoaded, false, 'List the available schemas.');
        mark('di_db_schema', schemaChoicesLoaded, schemaSelected, 'Select a schema.');
      }
      if (databaseUsesQuery()) mark('di_db_query', namespaceSessionReady, namespaceSessionReady && databaseResultSourceReady(), 'Enter the custom SQL query.');
      else {
        const databaseObjectsLoaded = DATABASE_TABLES.length > 0 || SOURCE_VARIABLES.some((v) => String(v && v.sourceType || '').toLowerCase() === 'database');
        mark('listSourceVariables', namespaceSessionReady && !databaseObjectsLoaded, false, 'List the available database tables/views.');
        mark('di_sheet_included', namespaceSessionReady && databaseObjectsLoaded, selectedSheetNames().length > 0, 'Add at least one database table/view to Included tables.');
      }
    }
    const featuresAssigned = roles.features.length > 0;
    const labelsAssigned = roles.labels.length > 0;
    const featureNamesOK = headerNamed || featureNameAssignmentsComplete(roles);
    mark('di_var_feature_select', true, featuresAssigned, 'Assign at least one feature input.');
    mark('di_var_feature_case', align === 'key_per_block' && featuresAssigned, featureKeysOK, 'Assign the Case-ID key for every feature block.');
    mark('di_var_featnames_select', !headerNamed, featureNamesOK, 'Assign exactly one feature-name variable to every feature block.');
    mark('di_var_featnames_feature', !headerNamed && featuresAssigned, featureNamesOK, 'Assign the feature-name variable to every feature block.');
    mark('di_var_label_select', needsLabels, labelsAssigned, 'Assign the required label input.');
    mark('di_var_label_case', needsLabels && align === 'key_per_block' && labelsAssigned, labelKeysOK, 'Assign the Case-ID key for every label block.');
    mark('di_var_covars_case', align === 'key_per_block' && roles.covariates.length > 0, covariateKeysOK, 'Assign the Case-ID key for every covariate block.');
    if (!headerNamed && roles.covariates.length > 0) {
      const manualCovNames = commaList(val('di_var_covarnames_manual')).length > 0;
      const vectorCovNames = roles.covariateNames.length > 0;
      if (manualCovNames) mark('di_var_covarnames_manual', true, true, 'Assigned covariates require names.');
      else if (vectorCovNames) mark('di_var_covarnames_select', true, true, 'Assigned covariates require names.');
      else {
        mark('di_var_covarnames_select', true, false, 'Assign a covariate-name variable or enter names manually.');
        mark('di_var_covarnames_manual', true, false, 'Assign a covariate-name variable or enter names manually.');
      }
    }
    if (align === 'row_order') mark('addIdVariable', true, roles.caseId.length === 1, 'Select exactly one Case-ID/PSN variable that identifies the rows.');
    if (align === 'shared_key') {
      const sharedKeyEl = document.getElementById('di_var_shared_key');
      const selectedShared = sharedKeyEl ? Array.from(sharedKeyEl.selectedOptions || []).map((o) => o.value) : [];
      const selectionMatchesApplied = !selectedShared.length || (selectedShared.length === APPLIED_SHARED_KEY_NAMES.length && APPLIED_SHARED_KEY_NAMES.every((name) => selectedShared.includes(name)));
      const sharedKeyApplied = APPLIED_SHARED_KEY_NAMES.length > 0 && selectionMatchesApplied;
      mark('applySharedKey', true, sharedKeyApplied, 'Select the ordered shared-key component(s), then apply them to every row-bearing block.');
    }
    return;
  }

  if (st === 'image-list' || st === 'surface-list') {
    const surfaceRoiNative = st === 'surface-list' && String(val('di_surface_space_mode') || '').toLowerCase() === 'roi_native';
    if (surfaceRoiNative) {
      const lhScalars = lineList(val('di_surface_roi_lh_scalars')).length;
      const lhAnnots = lineList(val('di_surface_roi_lh_annots')).length;
      const rhScalars = lineList(val('di_surface_roi_rh_scalars')).length;
      const rhAnnots = lineList(val('di_surface_roi_rh_annots')).length;
      const lhUsed = lhScalars > 0 || lhAnnots > 0 || (rhScalars === 0 && rhAnnots === 0);
      const rhUsed = rhScalars > 0 || rhAnnots > 0;
      mark('di_surface_roi_lh_scalars', lhUsed, lhScalars > 0 && lhScalars === lhAnnots, 'Provide matched LH scalar and annotation files.');
      mark('di_surface_roi_lh_annots', lhUsed, lhAnnots > 0 && lhScalars === lhAnnots, 'Provide matched LH scalar and annotation files.');
      mark('di_surface_roi_rh_scalars', rhUsed, rhScalars > 0 && rhScalars === rhAnnots, 'Provide matched RH scalar and annotation files.');
      mark('di_surface_roi_rh_annots', rhUsed, rhAnnots > 0 && rhScalars === rhAnnots, 'Provide matched RH scalar and annotation files.');
    } else {
      markSharedFileSourceReadiness(mark);
    }
    if (st === 'image-list' && !imageOOCVCanInheritMaskFromTraining()) mark('di_image_mask', true, !!val('di_image_mask').trim(), 'Select the brainmask or atlas space-defining image.');
    const explicitCases = String(val('di_image_case_mode') || 'legacy_spm').toLowerCase() === 'explicit';
    mark('di_image_case_ids', explicitCases, !!val('di_image_case_ids').trim(), 'Select the explicit case-ID variable.');
    markSharedAuxiliaryReadiness(mark);
    return;
  }

  if (st === 'connectivity') {
    const fmt = connectivityInputFormat();
    const hasSidecar = !!val('di_conn_atlas_label_file').trim();
    const legacyTable = fmt === 'table' && !hasSidecar && !!val('di_conn_table_edge_columns').trim();
    mark('di_conn_atlas_label_file', !legacyTable, hasSidecar && !!CONNECTIVITY_DESCRIPTOR_INSPECTION && !connectivityLocalizationBlocked(), 'Select and inspect the ROI description file.');
    mark('di_conn_atlas_file', hasSidecar && !connectivityCoordinatesComplete(), !!val('di_conn_atlas_file').trim(), 'Some nodes have no MNI coordinates in the ROI description file. Select a labelled atlas to locate them.');
    if (fmt === 'file_per_subject') {
      markSharedFileSourceReadiness(mark);
      mark('di_conn_mat_variable', CONN_MAT_VARIABLE_NEEDS_SELECTION, !!val('di_conn_mat_variable'), 'Select the matrix variable inside the MAT files.');
    } else if (fmt === 'array3d' || fmt === 'vectorized') mark('di_conn_data_var', true, !!val('di_conn_data_var'), 'Select the connectivity workspace variable.');
    else if (fmt === 'table') {
      mark('di_conn_table_var', true, !!val('di_conn_table_var') && !!CONNECTIVITY_TABLE_SCHEMA, 'Select and inspect the connectivity table.');
      mark('di_conn_table_case_column', !!CONNECTIVITY_TABLE_SCHEMA && !CONNECTIVITY_TABLE_SCHEMA.rowNamesPresent, !!val('di_conn_table_case_column'), 'Select the case-ID column because row names are empty.');
      mark('di_conn_table_edge_columns', !hasSidecar, !!val('di_conn_table_edge_columns').trim(), 'Enter explicit edge-column indices for the non-spatial table pathway.');
    }
    markSharedAuxiliaryReadiness(mark);
    mark('di_conn_weighting_mat_variable', CONN_WEIGHTING_MAT_VARIABLE_NEEDS_SELECTION, !!val('di_conn_weighting_mat_variable'), 'Select the weighting variable inside the MAT file(s).');
    return;
  }

  if (st === 'roi') {
    const fmt = roiInputFormat();
    if (fmt === 'cat12_files') {
      markSharedFileSourceReadiness(mark);
      mark('di_roi_case_ids', currentROICaseIDMode() === 'explicit', !!val('di_roi_case_ids'), 'Select the explicit Case-ID variable.');
      mark('di_roi_cat12_atlas', true, !!val('di_roi_cat12_atlas'), 'Inspect the first CAT12 file and select an atlas family.');
      mark('di_roi_cat12_measure', true, !!val('di_roi_cat12_measure'), 'Select a CAT12 ROI measurement.');
    } else if (fmt === 'workspace_matrix') {
      mark('di_roi_data_var', true, !!val('di_roi_data_var'), 'Select the subjects-by-ROI matrix.');
      mark('di_roi_matrix_case_ids', true, !!val('di_roi_matrix_case_ids'), 'Select the matrix Case-ID variable.');
    } else if (fmt === 'workspace_table') {
      mark('di_roi_table_var', true, !!val('di_roi_table_var'), 'Select the ROI table.');
      mark('di_roi_case_column', true, !!val('di_roi_case_column'), 'Enter the exact Case-ID column.');
      mark('di_roi_feature_columns', true, !!val('di_roi_feature_columns').trim(), 'Enter the explicit ROI feature columns.');
    } else if (fmt === 'table_file') {
      mark('di_roi_table_file', true, !!val('di_roi_table_file').trim(), 'Select the ROI table file.');
      mark('di_roi_case_column', true, !!val('di_roi_case_column'), 'Enter the exact Case-ID column.');
      mark('di_roi_feature_columns', true, !!val('di_roi_feature_columns').trim(), 'Enter the explicit ROI feature columns.');
    }
    if (fmt !== 'cat12_files') {
      mark('di_roi_sidecar_file', true, !!val('di_roi_sidecar_file').trim(), 'Select the ROI description file.');
      mark('di_roi_id_column', true, !!val('di_roi_id_column').trim(), 'Enter the ROI ID column.');
      mark('di_roi_name_column', true, !!val('di_roi_name_column').trim(), 'Enter the ROI name column.');
    }
    if (roiHasVolumetricProvenanceSelection()) mark('di_roi_atlas_file', true, !!val('di_roi_atlas_file').trim(), 'Select the labelled volumetric atlas.');
    else {
      mark('di_roi_hemi_column', fmt !== 'cat12_files', !!val('di_roi_hemi_column').trim(), 'Enter the hemisphere column from the ROI description file.');
      const lh = !!val('di_roi_lh_annotation').trim(); const rh = !!val('di_roi_rh_annotation').trim();
      mark('di_roi_lh_annotation', !rh, lh, 'Select at least one hemisphere annotation.');
      mark('di_roi_rh_annotation', !lh, rh, 'Select at least one hemisphere annotation.');
      mark('di_roi_lh_surface_geometry', lh, !!val('di_roi_lh_surface_geometry').trim(), 'Select the left display mesh matching the annotation.');
      mark('di_roi_rh_surface_geometry', rh, !!val('di_roi_rh_surface_geometry').trim(), 'Select the right display mesh matching the annotation.');
    }
    markSharedAuxiliaryReadiness(mark);
  }
}

