      rows.push(['Partly missing cases', fmtNumber(fs.nPartialMissingCases)]);
      rows.push(['All-missing cases', fmtNumber(fs.nAllNaNCases)]);
      rows.push(['All-NaN features', fmtNumber(fs.nAllNaNFeatures)]);
      rows.push(['Constant features', fmtNumber(fs.nConstantFeatures)]);
