  const finalCases = isKnownNumber(dataIOAudit.nFinalCases) ? Number(dataIOAudit.nFinalCases) : Number(nSubjects);
  const finalFeatures = isKnownNumber(dataIOAudit.nFinalFeatures) ? Number(dataIOAudit.nFinalFeatures) : Number(nFeatures);
  const finalLabels = isKnownNumber(dataIOAudit.nFinalLabelTargets) ? Number(dataIOAudit.nFinalLabelTargets) :
    (roleReport ? arr(roleReport.labels).length : (isKnownNumber(probe.nLabelTargets) ? Number(probe.nLabelTargets) : (probe.hasLabels === true || probe.labelSummary ? 1 : (probe.hasLabels === false ? 0 : NaN))));
  const finalCovariates = isKnownNumber(dataIOAudit.nFinalCovariates) ? Number(dataIOAudit.nFinalCovariates) :
    (roleReport ? arr(roleReport.covariates).length : (isKnownNumber(probe.nCovariates) ? Number(probe.nCovariates) : (probe.hasCovariates === false ? 0 : NaN)));
  const ready = isCommit || result.readyToImport === true;
