  const caseQCHtml = caseQCRows.length ? `<section class="diagnosticSection"><h2>Case QC</h2><p class="diagnosticSectionIntro">Case QC identifies cases with unusually many missing or outlying feature values. A high value is a signal to inspect the case, not an automatic exclusion.</p>${caseQCGrid}</section>` : '';

