/**
 * updateContextMenuItems  Update context menu items state or markup after user interaction or bridge refresh.
 * It supports DataIO browser page for import configuration, preview, QC and commit operations at a local helper boundary rather than changing MATLAB-side NeuroMiner state.
 */
function updateContextMenuItems() {
  const menu = document.getElementById('modalityContextMenu');
  if (!menu) return;
  const info = selectedInfo();
  const mode = storageMode(info);
  const hasSelection = !!info;
  const incomplete = isIncompleteModality(info);
  const canModify = canModifyTrainingModalities();
  const inOOCVMode = isOOCVManagerMode();
  const rules = {
    replace: canModify && hasSelection && !incomplete,
    resume: canModify && hasSelection && incomplete,
    delete: canModify && hasSelection,
    externalize: !inOOCVMode && hasSelection && mode === 'memory',
    relink: !inOOCVMode && hasSelection && (mode === 'external' || incomplete),
    resources: !inOOCVMode && hasSelection,
    reimport: !inOOCVMode && hasSelection && mode === 'external' && info.externalFileExists !== false,
    recipe: !inOOCVMode && hasSelection && !incomplete,
    qcSidecar: !inOOCVMode && artifactHasQCViewerCache(selectedQCArtifact())
  };
  menu.querySelectorAll('button[data-action]').forEach((btn) => {
    const action = btn.dataset.action;
    const enabled = !!rules[action];
    btn.disabled = !enabled;
    btn.style.display = (action === 'resume' && !incomplete) ? 'none' : '';
  });
}
