// Selection is presentation-only; MATLAB owns all mutation and lifecycle validation.
const COVARIATE_MANAGEMENT_SELECTION = new Set();

function renderCovariateManagement() {
  const names = arr(covariateSummaryState().names);
  const rows = document.getElementById('covariateManagementRows');
  if (!rows) return;
  rows.innerHTML = names.map((name, i) =>
    `<label class="covariateManagementRow"><input type="checkbox" data-covariate-index="${i+1}" ${COVARIATE_MANAGEMENT_SELECTION.has(i+1) ? 'checked' : ''}><span>${escapeHtml(String(name))}</span><span class="muted">${i+1}</span></label>`
  ).join('');
  const status = document.getElementById('covariateSelectionStatus');
  if (status) status.textContent = `${COVARIATE_MANAGEMENT_SELECTION.size} of ${names.length} selected`;
  setDisabled('deleteSelectedCovariates', !COVARIATE_MANAGEMENT_SELECTION.size);
  setDisabled('deleteAllCovariates', !names.length);
}

function openCovariateManagement() {
  if (!canModifyTrainingModalities()) {
    setMessage('Covariates are locked after training data import is finalized.', 'warn');
    return;
  }
  if (covariateSummaryState().available !== true) return;
  COVARIATE_MANAGEMENT_SELECTION.clear();
  const modal = document.getElementById('covariateManagementModal');
  modal.classList.remove('hidden');
  modal.setAttribute('aria-hidden', 'false');
  renderCovariateManagement();
}

function closeCovariateManagement() {
  const modal = document.getElementById('covariateManagementModal');
  modal.classList.add('hidden');
  modal.setAttribute('aria-hidden', 'true');
  COVARIATE_MANAGEMENT_SELECTION.clear();
}

function deleteManagedCovariates(deleteAll) {
  if (!canModifyTrainingModalities()) {
    setMessage('Covariates are locked after training data import is finalized.', 'warn');
    return;
  }
  const names = arr(covariateSummaryState().names);
  const indices = deleteAll ? names.map((_, i) => i+1) : [...COVARIATE_MANAGEMENT_SELECTION].sort((a,b) => a-b);
  if (!indices.length) return;
  const target = deleteAll ? 'all covariates' : `${indices.length} selected covariate(s)`;
  if (!confirm(`Permanently delete ${target} from NM.covars and NM.covnames?`)) return;
  matlabService('dataio_delete_covariates', matrixState, {covariateIndices: indices, timeout: 120}).then((res) => {
    if (!res || res.ok === false) {
      setMessage(`Could not delete covariates: ${stripText(res, 'Deletion failed.')}`, 'danger');
      return;
    }
    STATE = res.state;
    matrixState = STATE.matrixImport || matrixState;
    closeCovariateManagement();
    render(); syncCurrent();
    setMessage(res.message, stripKind(res));
  }, (err) => {
    setMessage(`Could not delete covariates: ${err.message || String(err)}`, 'danger');
  });
}

/**
 * deleteSelectedModality  Provide the delete selected modality helper used by DataIO browser page for import configuration, preview, QC and commit operations.
 * It belongs to the browser/MATLAB bridge path and must keep request payloads aligned with the MATLAB service contract.
 * Side effects: may send a request to the local MATLAB bridge and update browser-side UI state from the response.
 */
