  if (isImageSource() && previewPayload() && previewPayload().paged && previewPayload().persistedPreview) { await loadPersistedPreviewPage(Math.max(1, previewPage - 1)); return; }
  if (isImageSource() && previewPayload() && IMAGE_PREVIEW_FULL_ROWS.length) { previewPage = Math.max(1, previewPage - 1); renderImagePreview(null); return; }
  await runPreview(Math.max(1, previewPage - 1));
