/**
 * generateQCReport  Provide the generate qcreport helper used by DataIO browser page for import configuration, preview, QC and commit operations.
 * It belongs to the browser/MATLAB bridge path and must keep request payloads aligned with the MATLAB service contract.
 * Side effects: may send a request to the local MATLAB bridge and update browser-side UI state from the response.
 */
async function generateQCReport() {
  if (!qcReportAvailable()) {
    setMessage(previewAvailableForQC() ? 'Run Preview first to enable QC report generation.' : 'Run Preview first. QC report generation uses the current preview rows and selected subject-level QC metric.', 'warn');
    updateQCReportButton();
    return;
  }
  let outputDir = '';
  try {
    const pick = await fetch(API('/api/pickpath'), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ kind: 'directory', multiple: false, timeout: 240 })
    }).then((r) => r.json());
    const paths = arr(pick && (pick.paths || pick.path || pick.files || pick.file)).filter(Boolean);
    outputDir = paths.length ? String(paths[0] || '') : '';
  } catch (pickErr) {
    setMessage(`Could not select the QC report folder: ${pickErr.message || String(pickErr)}`, 'danger');
    return;
  }
  if (!outputDir) {
    setMessage('QC report generation cancelled: no output directory selected.', 'warn');
    return;
  }
  const metricKey = qcSelectedSubjectMetricKey();
  setMessage('Generating QC report bundle...', 'info');
  const progressTaskId = createProgressTaskId('dataio_qcreport');
  showProgressModal('Generating QC report', 'Writing DataIO QC tables, figures, HTML report, and PDF when supported locally.', 'The report uses the current preview and selected subject-level QC metric. It does not change the NM structure.', { progressTaskId });
  await allowProgressModalPaint();
  try {
    const res = await matlabService('dataio_generate_qc_report', matrixStateFromForm(false), {
      qc: previewQC(),
      diagnostics: LAST_PREVIEW_RESULT || {},
      outputDir,
      subjectMetric: metricKey,
      zThreshold: imageViewerQCThresholdValue ? imageViewerQCThresholdValue() : 3,
      timeout: 3600,
      progressTaskId
    });
    if (res && res.messages) renderImportDiagnostics(res);
    if (!res || res.ok === false) {
      setMessage(stripText(res, 'QC report generation failed.'), stripKind(res));
      return;
    }
    LAST_QC_REPORT = res || null;
    const msg = res && res.bundleDir ? `QC report generated: ${res.bundleDir}` : stripText(res, 'QC report generation finished.');
    setMessage(msg, stripKind(res));
  } catch (err) {
    setMessage(`Could not generate the QC report: ${err.message || String(err)}`, 'danger');
  } finally {
    hideProgressModal();
    updateActionButtons();
  }
}

