/**
 * commitImport  Provide the commit import helper used by DataIO browser page for import configuration, preview, QC and commit operations.
 * It belongs to the browser/MATLAB bridge path and must keep request payloads aligned with the MATLAB service contract.
 * Side effects: may send a request to the local MATLAB bridge and update browser-side UI state from the response.
 */
async function commitImport() {
  const reason = invalidReasonForAction('commit');
  if (reason) { setMessage(reason, 'warn'); return; }
  const st = materializationStateFromForm();
  await syncCurrent(true, true);
  const imageMode = isImageSource();
  const connectivityMode = isConnectivitySource();
  const roiMode = isROISource();
  const commitLabel = connectivityMode ? 'connectivity import' : (roiMode ? 'ROI import' : (imageMode ? 'imaging import' : 'matrix/table import'));
  let proceed = true;
  try {
    proceed = confirm(imageMode ? 'Import these imaging data into the current NM2 session? NM2 will first check labels, case selection, metadata, and image-space compatibility.' : (connectivityMode ? 'Import these connectivity data into the current NM2 session? NM2 will first check metadata, node/edge compatibility, and weighting maps.' : (roiMode ? 'Import these ROI data into the current NM2 session? NM2 will first check the ROI values and spatial reference.' : 'Import these data into the current NM2 session?')));
  } catch (confirmErr) {
    proceed = true;
  }
  if (!proceed) return;

  const progressTaskId = createProgressTaskId('dataio_commit');
  const previewWasPerformed = !!LAST_PREVIEW_RESULT;
  const hasPreviewMaterialization = !!previewMaterializationCacheKey();
  const commitDataLabel = imageMode ? 'imaging data' : (connectivityMode ? 'connectivity data' : (roiMode ? 'ROI data' : 'matrix/table data'));
  const previewReuseMessage = previewWasPerformed
    ? (hasPreviewMaterialization
      ? `A current Preview exists. NM2 will reuse its retained ${commitDataLabel} if they are still available; if the retained Preview was evicted, Commit will stop and ask you to run Preview again rather than reread the source silently.`
      : 'A Preview was run, but its retained materialization key is unavailable. Commit will stop and ask you to run Preview again rather than reread the source silently.')
    : `No current Preview data are available; NM2 will read the ${commitDataLabel} source once before import.`;
  showProgressModal(`Committing ${commitLabel}`, previewReuseMessage,
    imageMode ? 'This may take time for large archives or first-use compressed NIfTI files.' : (connectivityMode ? 'Large connectivity file sets or edge tables may take time.' : (roiMode ? 'CAT12 file sets and atlas/annotation validation may take time.' : 'MATLAB is processing the request.')), { progressTaskId });
  await allowProgressModalPaint();
  try {
    const res = await matlabService('dataio_commit_import', st, { materializationCacheKey: previewMaterializationCacheKey(), previewPerformed: previewWasPerformed ? 1 : 0, timeout: imageMode ? 7200 : (connectivityMode ? 2400 : (roiMode ? 3600 : 900)), progressTaskId });
    if (!res || res.ok !== true) {
      if (res) renderImportDiagnostics(res);
      if (res && res.state) {
        STATE = res.state;
        matrixState = STATE.matrixImport || matrixState;
        selectedIndex = null;
        render();
        formFromMatrixState();
        switchTab('overview');
        syncCurrent();
        setMessage(stripText(res, 'Commit returned a warning/error state but also supplied an updated NM overview. Overview was refreshed; inspect diagnostics.'), stripKind(res));
      } else {
        setMessage(stripText(res, 'Import failed or was blocked before NM was modified. Open diagnostics to identify the blocker.'), stripKind(res));
      }
      updateActionButtons();
      return;
    }
    renderImportDiagnostics(res);
    clearMaterialization(false);
    if (res.state) {
      STATE = res.state;
      matrixState = STATE.matrixImport || matrixState;
      selectedIndex = null;
      render();
      formFromMatrixState();
      switchTab('overview');
      syncCurrent();
    }
  } catch (err) {
    setMessage(`Commit failed: ${err.message || String(err)}`, 'danger');
    updateActionButtons();
  } finally {
    hideProgressModal();
  }
}

async function pickSharedSubjectFiles() {
  const ctx = sharedImportDefinitionContext();
  if (!ctx.subjectFilesSupported) { setMessage('The selected source format does not use a subject-file list.', 'warn'); return []; }
  const pick = await fetch(API('/api/pickpath'), { method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({ kind:'file', multiple:true, filter:ctx.fileFilter, timeout:240 }) }).then((r)=>r.json());
  return arr(pick.paths || pick.files || pick.path || pick.file).filter(Boolean);
}
function sharedSubjectFilesChanged() {
  const ctx = sharedImportDefinitionContext();
  if (ctx.roi && ctx.sourceFormat === 'cat12_files') {
    setPromptSelectOptions('di_roi_cat12_atlas', [], 'Inspect first file'); setPromptSelectOptions('di_roi_cat12_measure', [], 'Select atlas first'); ROI_CAT12_ATLASES=[];
    setROICAT12Status('Choose files, then inspect the first CAT12 file.');
  }
  if (ctx.connectivity && ctx.sourceFormat === 'file_per_subject') refreshConnectivityMatVariableAfterListChange('data', false);
  invalidateMaterialization(); matrixStateFromForm(); updateActionButtons();
}
async function addSharedSubjectFiles(toClass) {
  const ctx = sharedImportDefinitionContext();
  if (!ctx.active || !ctx.subjectFilesSupported) { setMessage('Select a file-per-subject input format before adding subject files.', 'warn'); return; }
  try {
    const files = await pickSharedSubjectFiles();
    if (!files.length) return;
    if (toClass === true) {
      saveActiveSharedSubjectClassTextarea(); ensureSharedSubjectClassLists();
      SUBJECT_FILE_CLASS_LISTS[SUBJECT_FILE_ACTIVE_CLASS_INDEX].files = arr(SUBJECT_FILE_CLASS_LISTS[SUBJECT_FILE_ACTIVE_CLASS_INDEX].files).concat(files);
      renderSharedSubjectClassControls();
    } else {
      setVal('di_shared_files', textFromLines(lineList(val('di_shared_files')).concat(files)));
    }
    sharedSubjectFilesChanged();
  } catch (err) { setMessage(`Could not select the subject files: ${err.message || String(err)}`, 'danger'); }
}
function mutateSharedSubjectFileList(action, direction) {
  const ctx = sharedImportDefinitionContext();
  const classMode = ctx.autoLabels;
  const id = classMode ? 'di_shared_class_files' : 'di_shared_files';
  if (action === 'remove') removeImagesFromTextarea(id);
  else if (action === 'move') moveImageLineInTextarea(id, direction);
  else if (action === 'clear') setVal(id, '');
  if (classMode) { saveActiveSharedSubjectClassTextarea(); renderSharedSubjectClassControls(); }
  sharedSubjectFilesChanged();
}
function selectedLineRange(textarea) {
  const lines = String(textarea.value || '').split(/\r?\n/);
  if (!lines.length) return { start: 0, end: 0, lines };
  const start = textarea.selectionStart;
  const end = textarea.selectionEnd;
  let idxStart = lines.length - 1, idxEnd = lines.length - 1, pos = 0;
  if (Number.isFinite(start) && Number.isFinite(end) && end > start) {
    for (let i = 0; i < lines.length; i++) { const p0 = pos; const p1 = pos + lines[i].length + 1; if (start < p1 && end >= p0) { idxStart = i; break; } pos = p1; }
    pos = 0;
    for (let i = 0; i < lines.length; i++) { const p0 = pos; const p1 = pos + lines[i].length + 1; if (end <= p1 && end > p0) { idxEnd = i; break; } pos = p1; }
    if (idxEnd < idxStart) idxEnd = idxStart;
  }
  return { start: idxStart, end: idxEnd, lines };
}
/**
 * replaceTextareaLines  Provide the replace textarea lines helper used by DataIO browser page for import configuration, preview, QC and commit operations.
 * It supports DataIO browser page for import configuration, preview, QC and commit operations at a local helper boundary rather than changing MATLAB-side NeuroMiner state.
 */
function replaceTextareaLines(id, lines) {
  setVal(id, textFromLines(lines));
}
/**
 * removeImagesFromTextarea  Provide the remove images from textarea helper used by DataIO browser page for import configuration, preview, QC and commit operations.
 * It supports DataIO browser page for import configuration, preview, QC and commit operations at a local helper boundary rather than changing MATLAB-side NeuroMiner state.
 */
function removeImagesFromTextarea(id) {
  const el = document.getElementById(id);
  if (!el) return;
  const r = selectedLineRange(el);
  r.lines.splice(r.start, r.end - r.start + 1);
  replaceTextareaLines(id, r.lines);
}
/**
 * moveImageLineInTextarea  Provide the move image line in textarea helper used by DataIO browser page for import configuration, preview, QC and commit operations.
 * It supports DataIO browser page for import configuration, preview, QC and commit operations at a local helper boundary rather than changing MATLAB-side NeuroMiner state.
 */
function moveImageLineInTextarea(id, direction) {
  const el = document.getElementById(id);
  if (!el) return;
  const r = selectedLineRange(el);
  if (r.start !== r.end) return;
  const j = r.start + direction;
  if (j < 0 || j >= r.lines.length) return;
  const tmp = r.lines[r.start];
  r.lines[r.start] = r.lines[j];
  r.lines[j] = tmp;
  replaceTextareaLines(id, r.lines);
}




