async function pickMatrixFile() {
  const reason = invalidReasonForAction('pickFile');
  if (reason) { setMessage(reason, 'warn'); return; }
  const st = sourceType();
  const filter = st === 'matfile' ? '*.mat' : '*.txt;*.csv;*.tsv;*.dat;*.xls;*.xlsx;*.xlsm';
  try {
    const res = await fetch(API('/api/pickpath'), { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ kind: 'file', multiple: st === 'matfile' || st === 'tablefile', filter }) }).then((r) => r.json());
    const paths = arr(res.paths);
    if (!paths.length) return;
    if (st === 'matfile') {
      const merged = Array.from(new Set(lineList(val('di_medit')).concat(paths)));
      setVal('di_medit', merged.join('\n'));
      applyVariableRoles({}, false);
      await listSourceVariables();
    } else if (st === 'tablefile') {
      const priorList = tableFileListSignature();
      const hadDiscoveredTableInventory = Boolean(TABLE_FILE_DISCOVERY_SIGNATURE);
      const merged = Array.from(new Set(lineList(val('di_table_file')).concat(paths)));
      setVal('di_table_file', merged.join('\n'));
      setVal('di_medit', merged[0] || '');
      setVal('di_groupmode', groupmodeForSource());
      markTableFileInventoryChanged();
      if (!priorList && !hadDiscoveredTableInventory) await refreshTableFileSources();
      else if (tableFileListSignature() !== priorList) {
        if (!confirmTableFileListChange()) { updateSourcePanels(); updateActionButtons(); return; }
        matrixStateFromForm(); updateSourcePanels(); updateActionButtons();
        setMessage('Table-file list changed. Refresh data sources to validate assignments, keys, and filters.', 'warn');
        return;
      }
    }
    invalidateMaterialization();
    updateSourcePanels();
  } catch (err) {
    setMessage(`Could not select the file: ${err.message || String(err)}`, 'danger');
  }
}

