    ROI_CAT12_ATLASES=arr(res.atlases); const names=ROI_CAT12_ATLASES.map((x)=>String(x.name || '')).filter(Boolean);
    setPromptSelectOptions('di_roi_cat12_atlas',names,'Select atlas family'); updateROICAT12Measurements();
