/**
 * inspectConnectivityMatVariablesFor  Provide the inspect connectivity mat variables for helper used by DataIO browser page for import configuration, preview, QC and commit operations.
 * It belongs to the browser/MATLAB bridge path and must keep request payloads aligned with the MATLAB service contract.
 * Side effects: may send a request to the local MATLAB bridge and update browser-side UI state from the response.
 */
async function inspectConnectivityMatVariablesFor(kind, announce, force) {
  if (!isConnectivitySource()) return;
  const isWeighting = kind === 'weighting';
  if (!isWeighting && connectivityInputFormat() !== 'file_per_subject') { clearConnectivityMatVariableState('data'); return; }
  const f = isWeighting ? firstConnectivityWeightingMatFileFromUI() : firstConnectivityMatFileFromUI();
  if (!f) { clearConnectivityMatVariableState(isWeighting ? 'weighting' : 'data'); return; }
  const sig = `${kind}|${f}`;
  if (force !== true && sig === getConnectivityMatVariableFileSignature(kind)) {
    updateConnectivityMatVariablePanels();
    return;
  }
  setConnectivityMatVariableFileSignature(kind, sig);
  const seq = isWeighting ? ++CONN_WEIGHTING_MAT_INSPECT_SEQ : ++CONN_MAT_INSPECT_SEQ;
  try {
    const res = await matlabService('dataio_connectivity_mat_variables', matrixStateFromForm(false), { filePath: f, timeout: 120 });
    if (isWeighting && seq !== CONN_WEIGHTING_MAT_INSPECT_SEQ) return;
    if (!isWeighting && seq !== CONN_MAT_INSPECT_SEQ) return;
    if (sig !== getConnectivityMatVariableFileSignature(kind)) return;
    const vars = arr(res.variables).map((v) => String(v || '').trim()).filter(Boolean);
    const selectId = isWeighting ? 'di_conn_weighting_mat_variable' : 'di_conn_mat_variable';
    const current = val(selectId);
    if (vars.length === 1) {
      if (isWeighting) { CONN_WEIGHTING_MAT_VARIABLE_CANDIDATES = vars; CONN_WEIGHTING_MAT_VARIABLE_NEEDS_SELECTION = false; }
      else { CONN_MAT_VARIABLE_CANDIDATES = vars; CONN_MAT_VARIABLE_NEEDS_SELECTION = false; }
      setMatVariableSelectorOptions(selectId, vars, vars[0], false);
      setVal(selectId, vars[0]);
      if (announce) setMessage(`${isWeighting ? 'Weighting' : 'Connectivity'} MAT variable inferred: ${vars[0]}.`, 'info');
    } else if (vars.length > 1) {
      if (isWeighting) { CONN_WEIGHTING_MAT_VARIABLE_CANDIDATES = vars; CONN_WEIGHTING_MAT_VARIABLE_NEEDS_SELECTION = true; }
      else { CONN_MAT_VARIABLE_CANDIDATES = vars; CONN_MAT_VARIABLE_NEEDS_SELECTION = true; }
      setMatVariableSelectorOptions(selectId, vars, current, true);
      if (current && vars.includes(current)) setVal(selectId, current);
      else setVal(selectId, '');
      if (announce) setMessage(`${isWeighting ? 'Weighting' : 'Connectivity'} MAT files need variable disambiguation. Candidate variables: ${vars.join(', ')}.`, 'warn');
    } else {
      clearConnectivityMatVariableState(isWeighting ? 'weighting' : 'data');
      if (announce) setMessage(stripText(res, `No square numeric variables found in the first ${isWeighting ? 'weighting' : 'connectivity'} MAT file.`), stripKind(res));
    }
    updateConnectivityMatVariablePanels();
    matrixStateFromForm(false);
    updateActionButtons();
  } catch (err) {
    setMessage(`Could not inspect the ${isWeighting ? 'weighting' : 'connectivity'} MAT-file variables: ${err.message || String(err)}`, 'danger');
  }
}
