/**
 * saveDraftInputSettingsBeforeClose  Provide the save draft input settings before close helper used by DataIO browser page for import configuration, preview, QC and commit operations.
 * It belongs to the browser/MATLAB bridge path and must keep request payloads aligned with the MATLAB service contract.
 * Side effects: may send a request to the local MATLAB bridge and update browser-side UI state from the response.
 */
async function saveDraftInputSettingsBeforeClose() {
  matrixStateFromForm(false, false);
  if (!matrixState || matrixState.draftDirty !== true) return { ok: true, saved: false };
  const enteredState = JSON.parse(JSON.stringify(matrixState));
  const res = await matlabService('dataio_save_draft', matrixState, { timeout: 60 });
  if (!res || res.ok === false) {
    throw new Error(stripText(res, 'Could not save the unfinished import settings.'));
  }
  if (res.state) {
    STATE = res.state;
    const backendState = STATE.matrixImport && typeof STATE.matrixImport === 'object' ? STATE.matrixImport : {};
    matrixState = enteredState;
    DATAIO_DERIVED_STATE_FIELDS.forEach((k) => { if (backendState[k] !== undefined) matrixState[k] = backendState[k]; });
    if (backendState.matrix && backendState.matrix.preview !== undefined) {
      matrixState.matrix = matrixState.matrix && typeof matrixState.matrix === 'object' ? matrixState.matrix : {};
      matrixState.matrix.preview = backendState.matrix.preview;
    }
    STATE.matrixImport = matrixState;
  }
  if (res.saved) {
    FORM_DIRTY = false;
    matrixState.draftDirty = false;
    setMessage(res.message || 'Unfinished import settings saved.', 'ok');
  }
  return res;
}

