  if (varind === null) return;
  const pick = await fetch(API('/api/pickpath'), { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ kind: 'file', multiple: false, filter: '*.mat', timeout: 240 }) }).then((r) => r.json()).catch((e) => ({ error: e.message }));
  const files = arr(pick.paths || pick.files || pick.path || pick.file).filter(Boolean);
