    if (!res || res.ok === false) throw new Error(stripText(res, 'Relinking OOCV/application modality failed.'));
    if (res.state) STATE = res.state;
    render(); syncCurrent(); setMessage(res.message || 'OOCV/application data modality relinked.', stripKind(res));
