/**
 * cancelImportTask  Return whether the cancel import task condition holds for the current UI state.
 * It belongs to the browser/MATLAB bridge path and must keep request payloads aligned with the MATLAB service contract.
 * Side effects: may send a request to the local MATLAB bridge and update browser-side UI state from the response.
 */
async function cancelImportTask() {
  if (!hasImportTask()) { switchTab('overview'); setMessage('No active import task to cancel.', 'info'); return; }
  if (!confirm('Cancel the current import task? No imported data will be changed.')) return;
  try {
    const res = await matlabService('dataio_cancel_import', matrixState, { timeout: 60 });
    if (!res || res.ok === false) throw new Error(stripText(res, 'Cancelling import task failed.'));
    if (res.state) STATE = res.state;
    matrixState = res.matrixImport || res.statePatch || (STATE.matrixImport || {});
    selectedIndex = null;
    selectedOOCVModalityIndex = null;
    formFromMatrixState();
    clearMaterialization(false);
    renderImportDiagnostics(null);
    render();
    switchTab('overview');
    syncCurrent();
    setMessage(res.message || 'Import task cancelled. No imported data were changed.', stripKind(res));
  } catch (err) {
    setMessage(`Could not cancel the import task: ${err.message || String(err)}`, 'danger');
  }
}

/**
 * finish  Provide the finish helper used by DataIO browser page for import configuration, preview, QC and commit operations.
 * It belongs to the browser/MATLAB bridge path and must keep request payloads aligned with the MATLAB service contract.
 * Side effects: may send a request to the local MATLAB bridge and update browser-side UI state from the response.
 */
async function finish() {
  try {
    await saveDraftInputSettingsBeforeClose();
    await syncCurrent(true, true);
    if (isWorkbenchChild()) {
      const res = await matlabService('app_child_return', matrixState, { source: 'dataio', timeout: 120 });
      if (res && res.ok === false) throw new Error(res.message || res.error || 'Returning to the workbench failed.');
      window.location.replace(window.NMBridgeNavigationURL ? window.NMBridgeNavigationURL(workbenchReturnUrl()) : workbenchReturnUrl());
      return;
    }
    await fetch(API('/api/close'), { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ closed: true, source: 'dataio_overview' }) });
    document.body.innerHTML = '<p style="font-family:system-ui;padding:20px">DataIO state saved. You can close this tab.</p>';
  } catch (err) {
    setMessage(`Could not close DataIO cleanly: ${err.message || String(err)}`, 'danger');
  }
}
