bind('ivToggleQC', 'click', async () => {
  const cfg = imageViewerQCConfig();
  if (!cfg) {
    setMessage('Run Preview first to enable viewer QC maps.', 'warn');
    updateImageViewerQCControls();
    return;
  }
  IMAGE_VIEWER_QC_ACTIVE = !IMAGE_VIEWER_QC_ACTIVE;
  updateImageViewerQCControls();
  if (SURFACE_VIEWER_MESH || isSurfaceSource()) {
    if (IMAGE_VIEWER_QC_ACTIVE) await prepareSurfaceViewerQCOverlay();
    else restoreSurfaceViewerBaseValues();
    return;
  }
  if (IMAGE_VIEWER_QC_ACTIVE) {
    await prepareImageViewerQCOverlay();
  } else {
    if (IMAGE_VIEWER_QC_OVERLAY) IMAGE_VIEWER_QC_OVERLAY.active = false;
    renderImageViewerClientSlice();
  }
});
bind('ivQCMetric', 'change', async () => {
  if (IMAGE_VIEWER_QC_OVERLAY) { IMAGE_VIEWER_QC_OVERLAY.active = false; IMAGE_VIEWER_QC_OVERLAY.rowIndex = -1; IMAGE_VIEWER_QC_OVERLAY.metricKey = ''; IMAGE_VIEWER_QC_OVERLAY.zData = null; }
  if (SURFACE_VIEWER_MESH) {
    if (SURFACE_VIEWER_MESH.qcOverlay) SURFACE_VIEWER_MESH.qcOverlay.active = false;
    updateImageViewerQCControls();
    if (IMAGE_VIEWER_QC_ACTIVE) await prepareSurfaceViewerQCOverlay();
    else scheduleSurfaceViewerRender();
    return;
  }
  updateImageViewerQCControls();
  if (IMAGE_VIEWER_QC_ACTIVE) await prepareImageViewerQCOverlay();
  else renderImageViewerClientSlice();
});
